window.EXPL={"세무사2016_53-42-2":{"f":"법원은 취소소송이 제기되기 전에는 처분의 집행정지결정을 할 수 없다.","w":"집행정지는 본안인 취소소송이 법원에 계속 중일 것을 전제로 하므로 소 제기 전에는 신청할 수 없다. 행정소송법 제23조 제2항.","c":"상"},"세무사2016_53-55-4":{"f":"소송요건이 흠결된 경우에는 각하판결을 하여야 한다.","w":"소송요건이 갖추어지지 않은 소는 본안 판단 없이 각하한다. 기각판결은 본안에서 청구가 이유 없을 때 하는 판결이다.","c":"상"},"세무사2017_54-66-1":{"f":"국가를 상대로 하는 당사자소송의 경우에는 가집행선고를 할 수 없다.","w":"(2022.2.24 헌법재판소 위헌결정 전 기준 X. 현행은 위헌결정으로 구 행정소송법 제43조가 효력을 잃어 국가를 상대로 한 당사자소송에서도 가집행선고를 할 수 있다.) 결정 전에는 제43조가 국가 상대 당사자소송의 가집행선고를 금지하고 있었다.","c":"중","old":1,"ow":"출제 당시 정답 X. 2022.2.24 헌법재판소 위헌결정(행정소송법 제43조)으로 지금은 국가를 상대로 한 당사자소송에서도 가집행선고를 할 수 있다."},"세무사2022_59-46-5":{"f":"취소소송에서의 행정심판과의 관계에 관한 규정은 무효등 확인소송의 경우에 준용하지 않는다.","w":"무효등 확인소송에는 행정심판전치(제18조)를 준용하지 않는다. 무효등 확인소송은 제소기간 제한과 행정심판 전치의 적용을 받지 않는다. 행정소송법 제38조 제1항.","c":"상"},"세무사2022_59-67-2":{"f":"의무이행소송에 관한 명문의 규정이 없고 판례도 이를 인정하지 않는다.","w":"판례는 행정청에 일정한 처분을 하도록 하는 의무이행소송을 허용하지 않는다. 행정소송법상 항고소송은 취소소송, 무효등 확인소송, 부작위위법확인소송 세 가지다.","c":"상"},"세무사2022_59-67-3":{"f":"부작위위법확인소송이란 행정청의 부작위가 위법하다는 것을 확인하는 소송이다.","w":"부작위위법확인소송의 대상은 행정청이 법령상 응답의무가 있는데도 아무 처분을 하지 않는 부작위뿐이다. 거부처분은 취소소송이나 무효등 확인소송으로 다툰다. 행정소송법 제4조 제3호.","c":"상"},"세무사2022_59-67-4":{"f":"취소소송에는 처분등의 일부 취소를 구하는 소송이 포함되나 적극적 변경을 구하는 소송은 포함되지 않는다.","w":"판례는 취소소송의 변경은 소극적 변경(일부 취소)만 가능하고, 처분을 다른 내용으로 바꾸라는 적극적 변경을 구하는 소송은 허용되지 않는다고 본다.","c":"상"},"세무사2022_59-67-5":{"f":"검사의 불기소처분은 항고소송의 대상이 될 수 없다.","w":"검사의 불기소처분은 형사소송법상 재정신청이나 헌법소원으로 다투며 행정소송의 대상이 아니다.","c":"상"},"세무사2023_60-41-1":{"f":"행정청의 단순한 부작위는 취소소송의 대상이 되지 않는다.","w":"취소소송의 대상은 처분등이다. 처분이 없는 단순한 부작위는 대상이 아니고, 법령상 신청권을 전제로 한 부작위는 부작위위법확인소송으로 다툰다.","c":"상"},"세무사2023_60-47-3":{"f":"검사의 공소에 대하여는 행정소송의 방법으로 공소의 취소를 구할 수 없다.","w":"검사의 공소 제기는 행정처분이 아니라 형사소송절차에서 다룰 사항이다. 행정소송의 대상이 되지 않는다.","c":"상"},"세무사2023_60-79-4":{"f":"간접강제는 무효등 확인소송에 준용되지 않는다.","w":"간접강제(제34조)는 거부처분취소소송과 부작위위법확인소송에만 준용된다(제38조 제2항). 무효등 확인소송에는 준용 규정이 없다.","c":"상"},"세무사2025_62-60-3":{"f":"토지구획정리조합으로부터 조합원에 대한 구 「토지구획정리사업법」상의 청산금채권을 양수한 사람은 당사자소송에 의하여 양수금의 지급을 구할 수 있다.","w":"구 토지구획정리사업법상 청산금은 공법상 법률관계이므로 그 지급청구는 민사소송이 아니라 공법상 당사자소송으로 한다.","c":"중"},"세무사2026_63-43-3":{"f":"헌법재판소에 따르면 대통령의 긴급재정경제명령은 헌법재판의 대상이 될 수 있다.","w":"헌법재판소는 대통령의 긴급재정경제명령이 국민의 기본권을 직접 침해하는 경우 헌법소원의 대상이 된다고 보았다(93헌마186). 다만 행정재판의 대상이 되는 처분은 아니다.","c":"중"},"세무사2026_63-78-1":{"f":"합의제 행정청이 한 처분에 대해서는 법률에 특별한 규정이 없는 한 합의제 행정청 자체가 피고가 된다.","w":"피고는 처분을 한 행정청인데, 합의제 행정청이 처분을 하면 그 합의제 기관 자체가 피고가 된다. 위원장이 피고가 되는 경우는 법에 특별한 규정이 있을 때뿐이다.","c":"상"},"세무사2016_53-43-3":{"f":"영업정지처분취소소송에서 일정기간의 영업정지가 정당하다고 판단되더라도 그 기간을 초과하는 부분만을 취소할 수 없고 처분 전부를 취소하여야 한다.","w":"재량행위인 영업정지는 법원이 적정 기간을 정해 그 초과 부분만 취소할 수 없고, 재량권 일탈ㆍ남용이면 처분 전부를 취소한다. 일부 취소는 처분이 가분이고 정당한 범위를 확정할 수 있을 때 가능하다.","c":"상"},"세무사2016_53-45-1":{"f":"당사자인 행정청과 그 밖의 관계행정청을 기속한다.","w":"취소판결의 기속력은 당사자인 행정청뿐 아니라 그 밖의 관계행정청에도 미친다. 행정소송법 제30조 제1항.","c":"상"},"세무사2016_53-45-2":{"f":"종전 거부처분 후에 발생한 새로운 사유를 내세워 다시 하는 거부처분은 기속력의 내용으로서 재처분에 해당할 수 있다.","w":"기속력은 변론종결 시까지의 사유에 대해서만 미치므로, 그 후에 생긴 새로운 사유로 다시 거부처분을 하는 것은 기속력에 저촉되지 않고 적법한 재처분이다.","c":"상"},"세무사2016_53-45-3":{"f":"기속력은 판결의 주문뿐 아니라, 그 전제가 되는 처분 등의 구체적 위법사유에 관한 이유 중의 판단에도 미친다.","w":"기속력은 주문과 함께 주문을 이끌어내는 데 필요한 이유에서 판단된 구체적 위법사유에도 미친다. 그래서 행정청은 같은 이유로 같은 처분을 반복할 수 없다.","c":"상"},"세무사2016_53-45-4":{"f":"기속력에 반하는 처분은 당연무효이다.","w":"취소판결의 기속력에 반하는 처분은 중대하고 명백한 하자가 있어 취소사유가 아니라 당연무효에 해당한다는 것이 판례다.","c":"상"},"세무사2016_53-70-1":{"f":"무효등확인소송에서는 사정판결을 할 수 없다.","w":"판례는 당연무효인 처분은 취소하여 유지할 이익 자체가 없으므로, 무효확인소송에서 사정판결을 할 수 없다고 본다. 행정소송법 제28조는 취소소송의 규정이다.","c":"상"},"세무사2016_53-70-2":{"f":"당사자의 명백한 주장이 없더라도 법원은 기록에 나타난 사정을 기초로 직권으로 판단할 수 있다.","w":"판례는 사정판결의 요건인 공공복리 판단에 당사자의 명백한 주장이 없어도 기록에 나타난 여러 사정을 기초로 법원이 직권으로 판단할 수 있다고 본다.","c":"상"},"세무사2016_53-70-3":{"f":"공공복리를 위한 사정판결의 필요성은 변론종결시를 기준으로 판단한다.","w":"사정판결에서 공공복리 적합 여부는 처분시가 아니라 판결시(사실심 변론종결시)를 기준으로 판단한다. 처분의 위법 여부는 처분시 기준이다.","c":"상"},"세무사2016_53-70-4":{"f":"사정판결을 하는 법원은 그 판결의 주문에 그 처분의 위법함을 명시하여야 한다.","w":"사정판결을 할 때에는 판결 주문에서 처분이 위법함을 명시하여야 한다. 행정소송법 제28조 제1항 후문.","c":"상"},"세무사2016_53-74-1":{"f":"취소소송의 기각판결에도 기판력이 인정된다.","w":"청구기각 확정판결도 소송물인 처분의 위법성 존부 판단에 기판력이 생긴다. 그래서 같은 처분의 무효를 다시 주장하는 후소에도 기판력이 미친다.","c":"상"},"세무사2016_53-74-2":{"f":"행정소송법은 기판력을 명시적으로 규정하고 있지 않다.","w":"행정소송법에는 기속력(제30조)과 제3자효(제29조) 규정만 있고 기판력에 관한 명문 규정은 없다. 민사소송법 규정이 준용되어 기판력이 인정된다.","c":"상"},"세무사2016_53-74-3":{"f":"기판력은 판결이유에 설시된 그 전제가 되는 법률관계의 존부에는 미치지 않는다.","w":"기판력은 판결 주문에 포함된 소송물에 관한 판단에만 미친다. 판결이유 중의 판단에는 미치지 않는다.","c":"상"},"세무사2016_53-74-5":{"f":"기판력은 당해 처분이 귀속되는 국가 또는 공공단체에도 미친다.","w":"행정청을 피고로 한 취소소송의 기판력은 그 처분이 귀속하는 국가 또는 공공단체에도 미친다.","c":"상"},"세무사2017_54-57-2":{"f":"기속력은 인용판결에서는 인정되나 기각판결과 각하판결에서는 인정되지 않는다.","w":"기속력은 처분을 취소하는 인용판결에서 행정청에게 생기는 효력이다. 기각판결이나 각하판결에서는 인정되지 않는다.","c":"상"},"세무사2017_54-72-1":{"f":"피고 행정청이 없게 된 경우, 처분등에 관한 사무가 귀속되는 국가 또는 공공단체를 피고로 한다.","w":"소 제기 뒤 피고 행정청이 없어지면 그 처분에 관한 사무가 귀속되는 국가 또는 공공단체가 피고가 되고, 소송종료를 선언하지 않는다. 행정소송법 제13조 제2항.","c":"상"},"세무사2017_54-72-3":{"f":"행정청이 처분을 취소 또는 변경함으로 인하여 청구가 각하 또는 기각된 경우, 소송비용은 피고의 부담으로 한다.","w":"처분을 취소ㆍ변경해서 원고가 소를 유지할 이익이 사라진 경우에는 원고가 패소한 것처럼 보여도 소송비용은 피고가 부담한다. 행정소송법 제32조.","c":"상"},"세무사2017_54-72-4":{"f":"행정소송에 대한 대법원판결에 의하여 명령ㆍ규칙이 법률에 위반된다는 것이 확정된 경우, 대법원은 그 사유를 행정안전부장관에게 통보하여야 한다.","w":"명령ㆍ규칙이 위법하다고 확정되면 대법원은 그 사유를 행정안전부장관에게 통보한다. 법무부장관이 아니다. 행정소송법 제6조 제1항.","c":"상"},"세무사2017_54-72-5":{"f":"취소판결에 의하여 권리 또는 이익의 침해를 받은 제3자가 그 확정판결에 대해 재심을 청구할 경우, 확정판결이 있음을 안 날로부터 30일 이내, 판결이 확정된 날로부터 1년 이내에 제기하여야 한다.","w":"제3자 재심청구는 확정판결이 있음을 안 날부터 30일, 판결이 확정된 날부터 1년 이내에 제기해야 하며 이 기간은 불변기간이다. 행정소송법 제31조.","c":"상"},"세무사2017_54-76-4":{"f":"전소에서 기각판결이 확정된 경우, 그 과세처분의 무효확인을 구하는 후소에도 기판력이 미친다.","w":"과세처분 취소소송의 기각 확정판결은 처분이 적법하다는 판단에 기판력이 생기므로, 같은 처분의 무효확인을 구하는 후소에도 미친다.","c":"상"},"세무사2017_54-78-2":{"f":"거부처분에 대한 무효확인판결이 확정되었음에도 행정청이 아무런 처분을 하지 않는 경우, 간접강제가 허용되지 않는다.","w":"간접강제는 거부처분취소판결과 부작위위법확인판결에만 준용되고, 무효확인판결에는 준용되지 않는다. 행정소송법 제38조 제2항.","c":"상"},"세무사2021_58-72-3":{"f":"법원은 원고에 대하여 상당한 구제방법을 취하거나 상당한 구제방법을 취할 것을 피고에게 명할 수 없다.","w":"사정판결을 할 때 법원은 원고가 입을 손해의 정도와 배상방법 등을 미리 조사할 뿐이며, 구제방법을 직접 취하거나 피고에게 명하는 권한은 없다. 원고가 같은 법원에 손해배상 등 청구를 병합해 제기할 수 있을 뿐이다(제28조 제2항ㆍ제3항).","c":"중"},"세무사2021_58-74-5":{"f":"행정청이 취소판결의 기속력에 반하는 행정처분을 하는 것은 허용되지 않으며 그 하자는 중대하고 명백하여 당연무효이다.","w":"기속력에 반하는 처분은 당연무효이다. 중대하고 명백한 하자가 있는 것으로 본다.","c":"상"},"세무사2021_58-75-4":{"f":"행정청이 판결의 취지에 따른 처분을 하지 아니하는 경우에 법원은 상당한 기간을 정하고 그 기간 내에 이행하지 아니하는 때에는 배상금을 명할 수 있다.","w":"간접강제는 거부처분취소판결에서 행정청이 재처분의무를 이행하지 않을 때 허용된다. 이전에 신청한 내용 그대로 처분할 의무는 없고 판결 취지에 따라 처분하면 된다(신청 거부도 가능). 행정소송법 제34조.","c":"상"},"세무사2021_58-76-2":{"f":"공사중지명령의 상대방은 그 명령의 취소를 구한 소송에서 그 명령이 적법함을 이유로 패소하여 확정된 이후에는 그 명령의 해제신청을 거부한 처분의 취소를 구하는 소송에서 그 명령의 적법성을 다툴 수 없다.","w":"전소 확정판결의 기판력은 공사중지명령이 적법하다는 판단에 미치므로, 후소에서 그 적법성을 다시 다툴 수 없다.","c":"상"},"세무사2021_58-77-5":{"f":"여러 처분사유에 관하여 하나의 제재처분을 하였을 때 그중 일부가 적법하지 않더라도 나머지 처분사유만으로 정당성이 인정되면 그 처분을 취소할 필요가 없다.","w":"여러 처분사유 중 일부가 인정되지 않아도 나머지 사유만으로 처분의 정당성이 인정되면 처분은 적법하므로 취소하지 않는다.","c":"상"},"세무사2021_58-78-3":{"f":"수익적 행정처분에 대한 취소판결은 처분이 위법하면 기득권의 침해를 정당화할 만한 중대한 공익상의 필요가 없더라도 허용된다.","w":"기득권 침해를 정당화할 중대한 공익상 필요나 제3자 이익보호 필요를 요구하는 것은 처분청이 스스로 하는 직권취소ㆍ철회의 제한 법리다. 법원이 위법한 처분을 취소하는 판결에는 그런 요건이 없다.","c":"중"},"세무사2022_59-61-1":{"f":"절차의 위법을 이유로 취소판결이 확정된 경우 B는 판결의 취지에 따라 다시 이전의 신청에 대한 처분을 하여야 한다.","w":"신청에 따른 처분이 절차의 위법을 이유로 취소된 경우에도 행정청은 판결의 취지에 따라 이전의 신청에 대하여 다시 처분을 하여야 한다. 행정소송법 제30조 제3항.","c":"상"},"세무사2022_59-61-2":{"f":"A가 소송에 참가할 경우, 면허처분을 취소하는 확정판결은 A에 대해서도 효력이 있다.","w":"처분을 취소하는 확정판결은 제3자에 대해서도 효력이 있다. 소송에 참가했다면 더욱 효력이 미친다. 행정소송법 제29조 제1항.","c":"상"},"세무사2022_59-61-4":{"f":"기각판결이 확정된 경우 그 판결은 B를 기속하지 않는다.","w":"기속력은 취소 인용판결에서만 생긴다. 기각판결은 기속력이 없어서 행정청은 직권으로 처분을 취소할 수도 있다.","c":"상"},"세무사2022_59-61-5":{"f":"소송 계속 중 B가 면허처분을 직권으로 취소하면 원칙적으로 소의 이익이 소멸한다.","w":"소송 중 처분이 직권취소되면 처분이 소멸하여 취소를 구할 대상과 이익이 없어지고, 소는 각하된다.","c":"상"},"세무사2022_59-71-1":{"f":"처분을 취소하는 확정판결의 기속력은 당사자인 행정청과 그 밖의 관계행정청에 대해서도 미친다.","w":"취소판결의 기속력은 당사자인 행정청뿐 아니라 그 밖의 관계행정청에도 미친다. 행정소송법 제30조 제1항.","c":"상"},"세무사2022_59-71-3":{"f":"거부처분을 취소하는 판결이 확정된 경우 처분청이 사실심 변론종결 이후의 사유를 내세워 다시 거부처분을 하는 것은 기속력에 저촉되지 않는다.","w":"기속력은 사실심 변론종결 시까지의 사유에 대해서만 미친다. 그 이후에 생긴 사유를 들어 다시 거부하는 것은 기속력에 저촉되지 않는다.","c":"상"},"세무사2022_59-71-4":{"f":"기속력에 저촉되는 행정처분은 당연무효이다.","w":"기속력에 반하는 후속 처분은 그 하자가 중대하고 명백하여 당연무효이다.","c":"상"},"세무사2022_59-71-5":{"f":"무효등 확인소송의 기각판결은 기속력이 없다.","w":"기속력은 취소 인용판결에서만 생기는 효력이다. 기각판결은 어느 소송에서든 기속력이 없다.","c":"상"},"세무사2022_59-72-1":{"f":"부적법한 소로서 그 흠을 보정할 수 없는 경우에는 판결로 소를 각하한다.","w":"소송요건을 갖추지 못한 부적법한 소는 본안 판단 없이 각하한다. 기각은 본안에서 이유 없는 경우에 하는 판결이다.","c":"상"},"세무사2022_59-72-3":{"f":"당사자소송의 인용판결에 대하여 제3자는 재심을 청구할 수 없다.","w":"제3자의 재심청구(제31조)는 취소소송의 규정으로, 당사자소송에는 준용되지 않는다(제44조 제1항).","c":"상"},"세무사2022_59-72-4":{"f":"자기에게 책임없는 사유로 취소소송에 참가하지 못했던 제3자가 판결의 결과에 영향을 미칠 공격 또는 방어방법을 제출하지 못한 때에는 재심을 청구할 수 있다.","w":"재심청구는 제3자가 자기에게 책임없는 사유로 소송에 참가하지 못해 공격ㆍ방어방법을 제출하지 못한 경우에 허용된다. 책임 있는 사유가 있으면 할 수 없다. 행정소송법 제31조 제1항.","c":"상"},"세무사2022_59-72-5":{"f":"무효확인판결이 확정된 날로부터 1년이 지나면 제3자는 재심을 청구할 수 없다.","w":"제3자의 재심청구기간은 확정판결이 있음을 안 날부터 30일, 판결이 확정된 날부터 1년이다. 180일이 아니라 1년이다. 행정소송법 제31조 제2항, 제38조 제1항.","c":"상"},"세무사2022_59-73-4":{"f":"소송참가인이었던 행정청이 소속하는 공공단체에도 소송비용 재판의 효력이 미친다.","w":"소송비용에 관한 재판이 확정되면 피고 또는 참가인이었던 행정청이 소속하는 국가 또는 공공단체에도 그 효력이 미친다. 행정소송법 제33조.","c":"상"},"세무사2022_59-74-1":{"f":"취소소송을 제기하더라도 처분의 효력은 정지되지 않는다.","w":"취소소송의 제기는 처분의 효력이나 집행을 정지시키지 않는 것(집행부정지)이 원칙이다. 효력을 멈추려면 따로 집행정지를 신청해야 한다. 행정소송법 제23조 제1항.","c":"상"},"세무사2022_59-74-2":{"f":"3개월의 영업정지 기간이 재량권을 넘는 과도한 것이라면 법원은 처분 전부를 취소하여야 한다.","w":"재량행위인 영업정지는 법원이 적정 기간을 정해 초과분만 취소할 수 없고, 재량권을 일탈ㆍ남용했다면 처분 전부를 취소한다.","c":"상"},"세무사2022_59-74-3":{"f":"소송이 제기된 후 A군수가 영업정지 기간을 1개월로 변경한 경우 변경이 있음을 안 날로부터 60일 이내에 甲은 처분변경으로 인한 소의 변경을 신청할 수 있다.","w":"처분변경으로 인한 소의 변경은 변경이 있음을 안 날부터 60일 이내에 신청한다(제22조 제2항). 다만 처분을 감경하는 변경은 당초 처분이 감경된 상태로 존속하는 것으로 보아 따로 소 변경이 필요하지 않다는 것이 판례다.","c":"중"},"세무사2022_59-74-4":{"f":"취소판결이 확정되면 A군수는 판결에 기속되며, 그 밖에 위법한 결과가 있으면 이를 제거하는 조치를 할 의무가 있다.","w":"취소판결의 기속력에는 판결로 위법이 확인된 처분의 결과를 제거할 의무(결과제거의무)가 포함된다.","c":"상"},"세무사2022_59-75-1":{"f":"처분이 부당하다고만 인정될 때에는 일부 취소의 판결을 할 수 없다.","w":"법원은 위법한 처분만 취소할 수 있다. 위법하지 않고 부당하기만 한 경우는 행정심판의 심리 대상이고 법원이 취소할 수 없다.","c":"상"},"세무사2022_59-75-2":{"f":"법원은 행정처분 당시 행정청이 알고 있었는지와 관계없이 사실심 변론종결 시까지 제출된 모든 자료를 종합하여 처분 당시 존재하였던 객관적 사실을 확정하고 그 사실에 기초하여 판단하여야 한다.","w":"행정처분의 위법 여부는 처분 당시를 기준으로 하되, 판단 자료는 행정청이 처분 때 알던 자료로 한정되지 않고 변론종결 시까지 제출된 모든 자료이다.","c":"상"},"세무사2022_59-75-3":{"f":"하나의 제재처분의 사유가 된 여러 개의 위반행위 중 일부의 위반행위에 대한 제재처분 부분만이 위법한 경우 제재처분이 가분이면 법원은 그 위법한 부분만을 취소하여야 한다.","w":"제재처분이 가분이어서 일부가 위법한 범위를 확정할 수 있으면 법원은 그 위법 부분만 취소한다. 전부 취소는 가분이 아니거나 범위를 특정할 수 없을 때다.","c":"중"},"세무사2022_59-75-4":{"f":"여러 개의 상이에 대한 국가유공자 요건 비해당결정처분에서 그중 일부 상이에 대해서만 국가유공자 요건이 인정될 경우 법원은 그 인정되는 부분만 취소하여야 한다.","w":"상이별로 요건 해당 여부를 가를 수 있으므로 처분은 가분이다. 요건이 인정되는 상이 부분에 한해 비해당결정을 취소한다.","c":"중"},"세무사2023_60-63-4":{"f":"공공복리를 위한 사정판결의 필요성은 변론종결시(판결시)를 기준으로 판단한다.","w":"사정판결에서 공공복리 적합 여부는 처분시가 아니라 사실심 변론종결 시를 기준으로 판단한다. 처분의 위법성만 처분시를 기준으로 한다.","c":"상"},"세무사2023_60-67-1":{"f":"간접강제는 거부처분취소소송과 부작위위법확인소송에 준용된다.","w":"간접강제(제34조)는 거부처분취소소송과 부작위위법확인소송에만 준용된다. 모든 항고소송에 준용되는 것은 아니다(무효등 확인소송 제외). 행정소송법 제38조 제2항.","c":"상"},"세무사2023_60-69-2":{"f":"취소청구가 사정판결에 의해 기각된 경우에는 소송비용은 피고가 부담한다.","w":"사정판결은 처분이 위법함을 전제로 하므로 청구는 기각되어도 소송비용은 피고가 부담한다. 행정소송법 제32조.","c":"상"},"세무사2024_61-45-1":{"f":"법원은 신청이 없더라도 직권으로 사정판결을 할 수 있다.","w":"사정판결은 당사자의 신청이 없어도 법원이 직권으로 할 수 있고, 당사자의 명백한 주장이 없어도 기록에 나타난 사정을 기초로 판단할 수 있다.","c":"상"},"세무사2024_61-45-2":{"f":"사정판결에서 ‘공공복리’의 판단 기준시는 변론종결시(판결시)이다.","w":"처분의 위법성은 처분시를 기준으로 하지만, 사정판결의 요건인 공공복리 적합 여부는 사실심 변론종결 시를 기준으로 판단한다.","c":"상"},"세무사2024_61-45-3":{"f":"법원은 사정판결을 하는 경우 그 판결의 주문에서 처분등이 위법함을 명시하여야 한다.","w":"사정판결에서는 이유가 아니라 주문에 처분이 위법함을 명시해야 한다. 이는 처분이 적법하다는 뜻이 아니라는 점을 분명히 하고, 이 부분에 기판력을 두기 위해서다. 행정소송법 제28조 제1항 후문.","c":"상"},"세무사2024_61-45-5":{"f":"원고는 손해배상이 필요하면 손해배상청구소송을 당해 취소소송이 계속된 법원에 병합하여 제기할 수 있다.","w":"사정판결로 청구가 기각되는 경우 원고는 피고 행정청이 속한 국가나 공공단체를 상대로 손해배상 등 적당한 구제방법의 청구를 같은 법원에 병합하여 제기할 수 있다. 행정소송법 제28조 제3항.","c":"상"},"세무사2024_61-47-5":{"f":"신청에 대한 인용처분이 절차상 위법을 이유로 취소되는 경우에 그 처분을 행한 행정청은 판결의 취지에 따라 다시 이전의 신청에 대한 처분을 하여야 한다.","w":"신청에 따른 처분이 취소되어 행정청에 재처분의무가 생기는 것은 절차의 위법을 이유로 취소된 경우뿐이다. 실체적 위법을 이유로 취소된 경우에는 이 규정이 적용되지 않는다. 행정소송법 제30조 제3항.","c":"중"},"세무사2024_61-48-5":{"f":"과세처분의 취소소송에서 청구가 기각된 확정판결의 기판력은 그 과세처분의 무효확인을 구하는 소송에도 미친다.","w":"기각 확정판결은 과세처분이 적법하다는 판단에 기판력이 생기므로, 그 처분이 무효라는 후소의 주장은 기판력에 저촉되어 배척된다.","c":"상"},"세무사2024_61-50-1":{"f":"판결은 관계행정청을 기속한다.","w":"취소판결의 기속력은 당사자인 행정청뿐 아니라 그 밖의 관계행정청에도 미친다. 행정소송법 제30조 제1항.","c":"상"},"세무사2024_61-50-3":{"f":"판결의 기속력은 처분의 구체적 위법사유에 관한 이유 중의 판단에 대하여도 인정된다.","w":"기속력은 판결 주문뿐 아니라 그 전제가 된 처분의 구체적 위법사유에 관한 이유 중의 판단에도 미친다.","c":"상"},"세무사2024_61-50-4":{"f":"乙이 재처분의무를 이행하지 않을 경우 법원은 간접강제로 판결의 실효성을 확보할 수 있다.","w":"우리 행정소송법에는 법원이 행정청을 대신해 처분하는 직접처분 제도가 없다. 거부처분취소판결의 실효성은 배상금을 부과하는 간접강제로 확보한다. 행정소송법 제34조.","c":"상"},"세무사2024_61-58-4":{"f":"간접강제결정은 피고 행정청이 속하는 국가 또는 공공단체에도 효력을 미친다.","w":"간접강제결정의 효력은 피고 또는 참가인이었던 행정청이 소속하는 국가 또는 공공단체에도 미친다. 행정소송법 제34조 제2항, 제33조.","c":"상"},"세무사2024_61-59-2":{"f":"재심청구는 확정판결이 있음을 안 날로부터 30일 이내에 제기하여야 한다.","w":"제3자의 재심청구는 확정판결이 있음을 안 날부터 30일 이내, 판결이 확정된 날부터 1년 이내에 제기해야 한다. 행정소송법 제31조 제2항.","c":"상"},"세무사2024_61-59-3":{"f":"소송에 참가하지 못한 제3자가 자기에게 책임없는 사유로 공격 또는 방어방법을 제출하지 못한 때에는 재심을 청구할 수 있다.","w":"제3자 재심은 책임없는 사유로 소송에 참가하지 못해 공격ㆍ방어방법을 제출하지 못한 경우에 청구할 수 있다. 이미 소송에 참가했던 자는 해당하지 않는다. 행정소송법 제31조 제1항.","c":"중"},"세무사2024_61-59-4":{"f":"부작위위법확인소송의 경우에도 재심청구가 인정된다.","w":"제3자의 재심청구는 부작위위법확인소송에도 준용된다. 행정소송법 제38조 제2항.","c":"상"},"세무사2024_61-59-5":{"f":"‘판결이 확정된 날로부터 1년 이내’라는 재심청구기간은 불변기간이다.","w":"제3자의 재심청구 기간은 불변기간이다. 행정소송법 제31조 제3항.","c":"상"},"세무사2025_62-42-5":{"f":"소송비용의 부담을 규정한 「행정소송법」 제32조는 당사자소송에 준용된다.","w":"소송비용 부담(제32조)과 소송비용 재판의 효력(제33조)은 당사자소송에 준용된다. 행정소송법 제44조 제1항.","c":"상"},"세무사2025_62-65-2":{"f":"항고소송의 판결서는 「행정소송법」에 규정된 특수한 기재방법이 없어 「민사소송법」에 따른다.","w":"행정소송법에는 판결서 기재방법에 관한 특별 규정이 없으므로 민사소송법을 준용하여 작성한다. 행정소송법 제8조 제2항.","c":"중"},"세무사2025_62-66-1":{"f":"사정판결은 종국판결에 해당한다.","w":"사정판결은 원고의 청구를 기각하는 판결이므로 소송을 끝내는 종국판결이다. 중간판결이 아니다.","c":"상"},"세무사2025_62-66-3":{"f":"사정판결은 극히 엄격한 요건 아래 예외적으로만 사용되어야 한다.","w":"사정판결은 위법한 처분을 유지하는 예외적인 제도이므로 극히 엄격한 요건 아래 제한적으로 적용해야 한다는 것이 판례다.","c":"상"},"세무사2025_62-66-4":{"f":"사정판결은 처분이 위법하지 않음이 확인되면 할 수 없다.","w":"사정판결은 처분이 위법하지만 취소하는 것이 현저히 공공복리에 적합하지 않을 때 하는 판결이다. 처분이 적법하면 청구를 기각하면 되고 사정판결의 대상이 아니다.","c":"상"},"세무사2025_62-66-5":{"f":"사정판결은 당사자의 신청이 없어도 직권으로 할 수 있다.","w":"법원은 당사자의 신청 없이도 직권으로 사정판결을 할 수 있다.","c":"상"},"세무사2025_62-67-1":{"f":"원고는 피고가 원고의 소를 일부 인정하는 경우 소의 취하를 할 수 있다.","w":"소의 취하는 소를 제기한 원고만 할 수 있다. 피고가 원고의 주장을 받아들이는 것은 인낙에 해당하고 취하가 아니다.","c":"중"},"세무사2025_62-67-2":{"f":"피고가 원고의 소송상 청구가 이유 있음을 자인하는 인낙은 사실심 종결 후에는 할 수 없다.","w":"청구가 이유 있음을 받아들이는 인낙은 피고가 하는 소송행위이다. 원고가 자기 청구가 이유 없다고 자인하는 것은 포기다. 행정소송에서는 처분권주의가 제한되어 포기ㆍ인낙은 허용되지 않는다는 것이 통설이다.","c":"중"},"세무사2025_62-67-4":{"f":"재판장이 소송계속 중인 사건에 대하여 처분등의 취소를 서면으로 권고하는 경우에는 이해관계인, 그 밖의 참고인을 심문할 수 있다.","w":"재판장의 소 취하ㆍ처분 취소 등의 권고는 서면으로 한다(행정소송규칙). 구두 권고는 규정되어 있지 않다.","c":"하"},"세무사2025_62-67-5":{"f":"청구의 포기는 원고가 할 수 있다.","w":"청구의 포기는 원고가 자기 청구가 이유 없음을 인정하는 소송행위로 원고만 할 수 있다. 피고가 하는 것은 청구의 인낙이다. 행정소송에서 허용 여부에는 처분권주의 제한 때문에 다툼이 있다.","c":"중"},"세무사2025_62-68-2":{"f":"처분을 취소하는 확정판결의 효력은 제3자에게도 미친다.","w":"처분등을 취소하는 확정판결은 소송 당사자뿐 아니라 제3자에 대해서도 효력이 있다(대세효). 행정소송법 제29조 제1항.","c":"상"},"세무사2025_62-69-1":{"f":"간접강제는 「행정소송법」에 규정되어 있으나 「민사집행법」 제262조(채무자의 심문)의 규정은 준용될 수 있다.","w":"행정소송법 제34조에 없는 절차는 민사집행법의 간접강제 규정을 준용한다는 것이 판례다. 그래서 채무자 심문 규정도 준용된다.","c":"중"},"세무사2026_63-59-1":{"f":"「행정소송법」 제30조제2항의 재처분의무를 이행하지 않은 경우에 법원이 결정할 수 있다.","w":"간접강제는 행정청이 거부처분취소판결의 취지에 따른 재처분의무를 이행하지 않을 때에 한해 신청할 수 있다. 이행 여부와 무관하게 하는 것이 아니다. 행정소송법 제34조 제1항.","c":"상"},"세무사2026_63-59-2":{"f":"간접강제결정에 기한 배상금은 확정판결의 취지에 따른 재처분의 지연에 대한 제재나 손해배상이 아니라 재처분의 이행에 관한 심리적 강제수단이다.","w":"판례에 따르면 간접강제의 배상금은 제재나 손해배상금이 아니고, 재처분을 하도록 압박하는 심리적 강제수단이다. 그래서 의무이행기한이 지난 뒤라도 재처분이 이루어지면 더 이상 추심할 수 없다.","c":"상"},"세무사2026_63-59-3":{"f":"간접강제는 당사자소송에는 적용되지 않는다.","w":"간접강제는 거부처분취소소송과 부작위위법확인소송에서만 허용되고, 당사자소송에는 준용 규정이 없다.","c":"상"},"세무사2026_63-59-5":{"f":"간접강제 결정은 변론 없이 할 수 있다.","w":"간접강제 결정은 신청에 대한 결정이므로 변론을 거치지 않고 할 수 있다. 다만 채무자인 행정청에 대한 심문은 거친다.","c":"상"},"세무사2026_63-66-5":{"f":"사정판결의 판단 기준시는 변론종결시(판결시)이다.","w":"처분의 위법성은 처분시를 기준으로 하지만, 사정판결에서 공공복리 적합 여부를 판단하는 기준시점은 사실심 변론종결 시이다.","c":"상"},"세무사2026_63-68-1":{"f":"과세처분에 대한 취소판결이 확정되어 그 처분이 처분시에 소급하여 소멸한 경우에는 그 후에 행정청이 경정처분을 하더라도 당연무효이다.","w":"과세처분이 판결로 취소되어 소급해서 없어지면, 존재하지 않는 처분을 경정하는 처분은 대상이 없어 당연무효이다.","c":"상"},"세무사2026_63-68-2":{"f":"어떠한 행정처분이 항고소송에서 취소되었다고 하여 기판력으로 곧바로 국가배상책임이 인정되는 것은 아니다.","w":"취소판결의 기판력은 처분의 위법성 존부에만 미치고, 국가배상책임에 필요한 공무원의 고의ㆍ과실을 곧바로 인정하는 효력은 없다는 것이 판례다. 위법성 판단과 과실 판단은 서로 다르다.","c":"상"},"세무사2026_63-68-3":{"f":"취소소송에서 전소와 후소가 그 소송물을 달리하는 경우에는 전소의 확정판결 기판력이 후소에 미치지 않는다.","w":"기판력은 전소와 후소의 소송물이 같거나, 후소 소송물에 선결문제이거나 모순관계에 있는 경우에 미친다. 소송물이 다르면 원칙적으로 미치지 않는다.","c":"중"},"세무사2026_63-68-5":{"f":"거부처분취소판결이 확정된 후 법령이 개정ㆍ시행된 경우에는 개정된 법령을 새로운 사유로 들어 다시 이전의 신청에 대한 거부처분을 할 수 있다.","w":"기속력은 변론종결 시까지의 사유에 미치므로 판결 후에 개정ㆍ시행된 법령을 새로운 사유로 삼아 다시 거부하는 것은 기속력에 저촉되지 않는다.","c":"상"},"세무사2021_58-59-4":{"f":"이른바 예탁금회원제 골프장의 기존회원은 골프장시설업자의 회원모집계획서에 대한 시ㆍ도지사의 검토결과통보의 취소를 구할 원고적격이 있다.","w":"예탁금회원제 골프장의 기존 회원은 회원모집계획서에 대한 시ㆍ도지사의 검토결과통보로 회원의 권익이 침해되므로 취소를 구할 법률상 이익이 있다는 것이 판례다.","c":"중"},"세무사2021_58-61-1":{"f":"「산업집적활성화 및 공장설립에 관한 법률」에 따라 공장설립승인처분 후에 공장건축허가처분이 있은 경우, 공장설립승인처분이 취소된 이후에도 공장건축허가처분의 취소를 구할 이익이 있다.","w":"공장설립승인이 취소되더라도 이를 기초로 한 건축허가가 남아 있는 한 그 허가의 취소를 구할 법률상 이익이 있다는 것이 판례다.","c":"중"},"세무사2021_58-61-2":{"f":"과세관청이 직권으로 법인세법상 소득처분을 경정하면서 일부 항목은 증액을 하고 동시에 다른 항목은 감액을 한 결과 전체로서 소득처분금액이 감소된 경우, 소득금액 변동통지의 취소를 구할 이익이 없다.","w":"전체로서 소득처분금액이 감소한 이상 종전 소득처분보다 불이익이 늘지 않았으므로 소득금액 변동통지의 취소를 구할 이익이 없다는 취지의 판례이다.","c":"중"},"세무사2021_58-61-3":{"f":"파면처분이 있은 후에 금고 이상의 형을 선고받아 당연퇴직사유가 발생한 경우에도, 파면 처분의 취소를 구할 이익이 있다.","w":"파면처분은 퇴직급여 감액 등 법률상 불이익이 따르므로, 사후에 당연퇴직사유가 생겼어도 파면처분의 취소를 구할 이익이 남는다.","c":"중"},"세무사2021_58-61-5":{"f":"행정청이 공무원에 대하여 직위해제처분을 한 후 다시 새로운 직위해제사유에 기한 직위해제처분을 한 경우, 이전에 한 직위해제처분의 취소를 구할 이익이 없다.","w":"새로운 직위해제처분이 있으면 종전 직위해제처분은 효력을 잃으므로 그 취소를 구할 소의 이익이 없다.","c":"상"},"세무사2022_59-52-1":{"f":"행정청이 공무원에 대하여 새로운 직위해제사유에 기하여 직위해제처분을 한 경우, 그 공무원에게는 이전의 직위해제처분의 취소를 구할 소의 이익이 인정되지 아니한다.","w":"종전 직위해제처분은 후속 직위해제처분에 의해 효력을 상실하여 그 취소를 구할 소의 이익이 없다는 것이 판례다.","c":"상"},"세무사2022_59-52-2":{"f":"건물의 신축과정에서 피해를 입은 인접주택 소유자는 신축건물에 대한 사용검사(사용승인)처분의 취소를 구할 소의 이익이 없다.","w":"사용승인처분은 건축허가대로 완공되었는지 확인하는 처분일 뿐이고, 인접주택 소유자의 법률상 이익을 직접 침해하지 않는다는 것이 판례이다.","c":"중"},"세무사2022_59-52-4":{"f":"가중 제재처분 규정이 있는 의료법에 의해 의사면허자격정지처분을 받은 경우 자격정지기간이 지난 후에도 의사면허자격정지처분의 취소를 구할 소의 이익이 인정된다.","w":"자격정지 처분 경력이 후속 처분의 가중 사유가 되는 규정이 있으면, 정지기간이 지났어도 취소를 구할 법률상 이익이 남아 있다.","c":"상"},"세무사2022_59-52-5":{"f":"치과의사국가시험에 불합격한 후 새로 실시된 국가시험에 합격한 경우에는 불합격처분의 취소를 구할 소의 이익이 인정되지 아니한다.","w":"새 시험에 합격했다면 불합격처분을 취소해도 얻을 법률상 이익이 없다. 명예 등 인격적 이익의 침해는 법률상 이익이 아니라고 본 판례이다.","c":"중"},"세무사2022_59-59-4":{"f":"처분의 상대방이 위명(僞名)을 사용한 사람인 경우에도 처분의 취소를 구할 법률상 이익이 인정된다.","w":"위명을 사용했다는 사정만으로 처분 상대방의 법률상 이익이 부정되지는 않는다. 처분의 효과가 그에게 미치기 때문이다.","c":"중"},"세무사2023_60-48-2":{"f":"국가는 국토이용계획과 관련한 지방자치단체장의 기관위임사무 처리에 관하여 지방자치단체장을 상대로 취소소송을 제기할 수 없다.","w":"기관위임사무는 국가가 지휘ㆍ감독할 수 있으므로 국가가 지방자치단체장을 상대로 취소소송을 제기할 이익이 없다. 지방자치단체장은 국가기관의 지위에서 사무를 처리한다.","c":"중"},"세무사2024_61-61-3":{"f":"사실적ㆍ경제적 이해관계를 갖는 데 불과한 경우에는 무효등 확인소송의 원고적격이 인정되지 않는다.","w":"무효등 확인소송의 원고적격도 처분의 효력 유무 확인을 구할 법률상 이익이 있어야 한다. 사실상ㆍ경제상 이해관계만으로는 부족하다. 행정소송법 제35조.","c":"상"},"세무사2025_62-46-3":{"f":"개발제한구역 안에서의 공장설립을 승인한 처분이 쟁송취소되었더라도, 그 승인처분에 기초한 공장건축허가처분이 잔존한다면 인근 주민은 공장건축허가처분의 취소를 구할 법률상 이익이 있다.","w":"공장설립승인이 취소되어도 이를 기초로 한 공장건축허가가 남아 있는 한 인근 주민이 그 허가의 취소를 구할 법률상 이익이 있다는 것이 판례다.","c":"중"},"세무사2016_53-47-4":{"f":"작위의무확인소송은 무효등확인소송에 포함되지 않는다.","w":"행정청이 일정한 행위를 할 의무가 있음을 확인하는 작위의무확인소송은 행정소송법상 인정되지 않는 소송이다. 무효등 확인소송은 처분의 효력 유무나 존재 여부를 확인하는 소송이다.","c":"상"},"세무사2016_53-52-1":{"f":"부작위위법확인소송에서 법원은 부작위의 효력이나 그 집행 또는 절차의 속행의 정지를 결정할 수 없다.","w":"집행정지는 처분의 효력이나 집행을 멈추는 제도다. 처분이 없는 부작위에는 정지할 대상이 없어 부작위위법확인소송에 준용되지 않는다. 행정소송법 제38조 제2항.","c":"상"},"세무사2016_53-52-3":{"f":"부작위위법확인판결의 효력으로서 재처분의무는 당초 신청된 특정 처분을 해야 하는 것이 아니라 어떠한 처분이든 하면 되는 것이다.","w":"부작위위법확인판결에 따라 행정청은 신청에 대해 인용이든 거부든 어떤 처분이든 하면 의무를 이행한 것이다. 신청한 대로 처분할 의무는 없다. 행정소송법 제38조 제2항, 제30조 제2항.","c":"상"},"세무사2016_53-52-4":{"f":"부작위위법확인소송에서는 사정판결을 할 수 없다.","w":"사정판결 규정(제28조)은 부작위위법확인소송에 준용되지 않는다. 행정소송법 제38조 제2항.","c":"상"},"세무사2016_53-52-5":{"f":"부작위위법확인판결의 효력은 제3자에게도 미친다.","w":"취소판결의 제3자효(제29조)는 부작위위법확인소송에 준용되어 제3자에게도 효력이 있다. 행정소송법 제38조 제2항.","c":"상"},"세무사2016_53-65-1":{"f":"부작위의 개념에는 거부처분이 포함되지 않는다.","w":"부작위는 행정청이 신청에 대하여 상당한 기간 안에 처분을 하여야 할 법률상 의무가 있는데도 아무 처분을 하지 않은 상태를 말한다. 거부처분은 처분이므로 부작위가 아니다. 행정소송법 제2조 제1항 제2호.","c":"상"},"세무사2016_53-65-3":{"f":"부작위위법의 확인을 구할 법률상 이익이 있는 자는 신청을 한 경우에 한하여 부작위위법확인소송을 제기할 수 있다.","w":"부작위위법확인소송은 처분의 신청을 한 자로서 부작위의 위법 확인을 구할 법률상 이익이 있는 자만 제기할 수 있다. 행정소송법 제36조.","c":"상"},"세무사2016_53-65-4":{"f":"행정심판 등 전심절차를 거친 경우 부작위위법확인소송은 제소기간의 제한을 받는다.","w":"행정심판 등 전심절차를 거친 경우 부작위위법확인소송은 재결서 정본을 송달받은 날부터 90일 이내에 제기해야 한다. 전심을 거치지 않았다면 부작위가 계속되는 한 제소기간 제한이 없다. 행정소송법 제38조 제2항, 제20조.","c":"상"},"세무사2016_53-65-5":{"f":"부작위의 상태가 계속되는 경우에는 전심절차를 거치지 않는 한 제소기간의 제한이 없다.","w":"부작위 상태가 계속되는 동안은 제소기간의 제한이 없다. 법원이 결정으로 제소기간을 정하는 제도는 없다. 전심절차를 거쳤다면 그 때에만 제소기간이 적용된다.","c":"상"},"세무사2016_53-72-2":{"f":"무효등확인소송의 전심절차로서 행정심판을 거친 경우에도 제소기간의 규정이 준용되지 않는다.","w":"무효등 확인소송에는 제소기간 규정(제20조)이 준용되지 않으므로 행정심판을 거쳤더라도 제소기간 제한이 없다. 행정소송법 제38조 제1항.","c":"상"},"세무사2016_53-72-3":{"f":"집행정지의 규정이 준용된다.","w":"집행정지(제23조)는 무효등 확인소송에 준용된다. 가처분이 이용되는 것이 아니다. 행정소송법 제38조 제1항.","c":"상"},"세무사2016_53-72-4":{"f":"취소소송 대상에 관한 규정이 준용되어 취소소송과 대상적격이 같다.","w":"무효등 확인소송에도 취소소송의 대상인 ‘처분등’에 관한 규정(제19조)이 준용되므로 대상적격이 더 넓게 인정되는 것은 아니다. 행정소송법 제38조 제1항.","c":"상"},"세무사2016_53-72-5":{"f":"피고적격에 관한 규정이 준용되어, 무효등확인소송의 피고는 처분등을 행한 행정청이다.","w":"무효등 확인소송에도 취소소송의 피고적격(제13조)이 준용되어 피고는 처분등을 한 행정청이다. 국가나 공공단체가 피고가 되는 소송은 당사자소송이다.","c":"상"},"세무사2017_54-48-2":{"f":"집행정지가 인정된다.","w":"집행정지 규정(제23조)은 무효등 확인소송에 준용된다. 행정소송법 제38조 제1항.","c":"상"},"세무사2017_54-48-3":{"f":"즉시확정의 이익이 요구되지 않는다.","w":"판례에 따르면 무효등 확인소송에서 확인소송의 보충성이나 즉시확정의 이익은 별도로 요구되지 않는다. 법률상 이익이 있으면 된다.","c":"상"},"세무사2017_54-48-4":{"f":"피고는 원칙적으로 그 처분등을 행한 행정청이다.","w":"피고는 처분을 한 행정청이지만, 권한이 승계된 경우처럼 다른 행정청이 피고가 되거나 행정청이 없어진 경우 국가나 공공단체가 피고가 되는 예외가 있어 언제나 그런 것은 아니다. 행정소송법 제13조.","c":"상"},"세무사2017_54-48-5":{"f":"제3자의 소송참가가 허용된다.","w":"제3자의 소송참가(제16조)는 무효등 확인소송에 준용된다. 행정소송법 제38조 제1항.","c":"상"},"세무사2017_54-60-1":{"f":"부작위위법확인소송 중 피고가 원고의 해당 신청에 대해 거부처분을 한 경우에는 소의 이익이 상실된다.","w":"소송 중에 행정청이 신청에 대해 인용이든 거부든 처분을 하면 부작위 상태가 해소되어 소의 이익이 사라진다.","c":"상"},"세무사2017_54-60-2":{"f":"원고에게 법규상 또는 조리상의 신청권이 있어야 한다.","w":"판례는 부작위위법확인소송에서 법규상 또는 조리상 신청권이 있어야 부작위가 성립하고 원고적격도 인정된다고 본다.","c":"상"},"세무사2017_54-60-3":{"f":"법원이 위법성 여부를 판단하는 기준시점은 판결시(사실심 변론종결시)이다.","w":"부작위위법확인소송은 판결 시까지 부작위 상태가 위법한지를 확인하는 소송이므로 처분시가 아니라 사실심 변론종결 시를 기준으로 판단한다.","c":"상"},"세무사2017_54-60-4":{"f":"부작위위법확인소송에 대해서는 행정심판의 전치에 관한 규정이 준용된다.","w":"행정심판 임의주의 규정(제18조)은 부작위위법확인소송에 준용된다. 행정소송법 제38조 제2항.","c":"상"},"세무사2021_58-44-1":{"f":"신청권의 존부는 본안판단이 아니라 소송요건의 문제이다.","w":"판례는 신청권의 유무를 부작위위법확인소송의 대상적격과 원고적격이라는 소송요건 단계에서 판단하고, 본안에서 따지지 않는다.","c":"중"},"세무사2021_58-45-4":{"f":"무효등 확인소송에서는 즉시확정의 이익이 요구되지 않는다.","w":"대법원 전원합의체 판결에 따르면 무효등 확인소송에는 보충성이나 즉시확정의 이익이 요구되지 않는다. 법률상 이익이 있으면 된다.","c":"상"},"세무사2021_58-50-1":{"f":"당사자의 신청은 내용상 적법하지 않아도 된다.","w":"부작위가 성립하려면 신청이 있고 이에 대해 응답할 법률상 의무가 있으면 족하고, 신청의 내용이 적법할 필요는 없다.","c":"중"},"세무사2022_59-63-1":{"f":"무효등 확인소송에서는 처분의 존재 여부가 심리의 대상이 될 수 있다.","w":"무효등 확인소송은 처분등의 효력 유무 또는 존재 여부를 확인하는 소송이므로 처분의 존재 여부도 심리 대상이다. 행정소송법 제4조 제2호.","c":"상"},"세무사2022_59-63-2":{"f":"작위의무확인소송은 무효등 확인소송의 일종으로 허용되지 않는다.","w":"행정청에 일정한 작위의무가 있음을 확인하는 소송은 행정소송법상 허용되지 않는 소송유형이다.","c":"상"},"세무사2022_59-63-3":{"f":"무효확인소송에서는 그 제기요건으로 보충성이 요구되지 않으므로, 행정처분의 무효를 전제로 한 이행소송 등과 같은 직접적인 구제수단이 있는지 여부를 따질 필요가 없다.","w":"무효확인소송에 보충성은 요구되지 않는다. 직접적인 구제수단이 따로 있어도 법률상 이익이 있으면 제기할 수 있다는 것이 대법원 전원합의체 판결이다.","c":"상"},"세무사2022_59-63-4":{"f":"처분의 당연무효를 선언하는 의미에서 그 취소를 구하는 행정소송을 제기한 경우에도 제소기간의 제한을 받는다.","w":"무효를 선언하는 의미의 취소소송도 취소소송의 형식이므로 제소기간(처분이 있음을 안 날부터 90일)과 전심절차의 요건을 갖추어야 한다.","c":"상"},"세무사2022_59-68-4":{"f":"행정심판 등 전심절차를 거친 경우에는 제소기간의 제한을 받는다.","w":"부작위위법확인소송도 행정심판 등 전심절차를 거쳤다면 재결서 정본을 송달받은 날부터 90일 이내라는 제소기간이 적용된다. 행정소송법 제38조 제2항, 제20조.","c":"상"},"세무사2023_60-72-3":{"f":"무효확인소송의 전심절차로서 행정심판을 거친 경우에도 제소기간을 준수할 필요가 없다.","w":"무효등 확인소송에는 제소기간 규정이 적용되지 않으므로 행정심판을 거쳤어도 제소기간 제한이 없다. 행정소송법 제38조 제1항.","c":"상"},"세무사2023_60-74-2":{"f":"처분등의 실효확인소송은 무효등 확인소송의 일종이다.","w":"무효등 확인소송에는 무효확인, 유효확인, 실효확인, 존재확인, 부존재확인 소송이 포함된다.","c":"상"},"세무사2023_60-75-2":{"f":"부작위위법확인소송에서 인용판결의 기속력으로서 재처분의무는 신청에 대하여 어떠한 처분이든 하여야 할 의무를 의미한다.","w":"재처분의무는 신청을 인용하는 처분이든 거부하는 처분이든 처분을 하라는 의무이고 특정 내용의 처분을 할 의무가 아니다.","c":"상"},"세무사2024_61-52-4":{"f":"甲이 제기한 소송에서 무효사유가 증명되지 아니하였더라도 법원은 취소사유의 유무까지 심리하여야 한다.","w":"무효확인을 구하는 청구에는 그 처분이 무효가 아니라면 취소를 구하는 취지가 포함되어 있다고 본다. 취소소송 요건을 갖추었다면 취소사유가 있는지 심리해야 한다.","c":"중"},"세무사2024_61-53-1":{"f":"부작위위법확인소송의 대상인 부작위가 되기 위해서는 당사자의 신청이 내용적으로 적법한 것일 필요는 없다.","w":"부작위가 되려면 법령상 신청권에 기한 신청이 있고 행정청에 응답할 의무가 있으면 되고, 신청의 내용이 적법할 필요는 없다.","c":"중"},"세무사2024_61-53-2":{"f":"부작위위법확인소송이 적법하게 제기되었더라도 소송계속 중 신청에 대한 거부처분이 있으면 해당 소송은 소의 이익이 없어 부적법하게 된다.","w":"소송 중 행정청이 신청에 대해 소극적 처분(거부)을 하면 부작위 상태가 해소되어 소의 이익이 없어진다.","c":"상"},"세무사2024_61-53-3":{"f":"행정입법 제정의무가 있는 경우에도 입법부작위는 부작위위법확인소송의 대상이 되지 않는다.","w":"부작위위법확인소송의 대상은 처분에 대한 부작위이다. 입법부작위는 처분이 아니므로 대상이 되지 않는다.","c":"상"},"세무사2024_61-53-5":{"f":"부작위의 위법을 확인하는 법원의 판결이 확정되면 행정청은 판결의 취지에 따라 이전의 신청에 대하여 처분을 하여야 할 의무가 있다.","w":"행정청은 신청에 대해 처분을 할 의무가 있을 뿐, 원고가 신청한 대로 처분해야 하는 것은 아니다. 거부처분도 가능하다.","c":"상"},"세무사2025_62-71-5":{"f":"외형상 하나의 행정처분이라도 가분성이 있거나 그 처분대상의 일부가 특정될 수 있다면 일부만의 무효확인도 할 수 있다.","w":"처분이 가분이고 무효인 범위를 특정할 수 있으면 법원은 일부에 대해서만 무효확인판결을 할 수 있다.","c":"상"},"세무사2025_62-73-1":{"f":"형사본안사건에서 무죄가 선고되어 확정됨에 따라 압수물의 환부를 피압수자가 신청하였는데 검사가 아무런 결정이나 통지를 하지 않고 있더라도 그와 같은 검사의 부작위는 부작위위법확인소송의 대상이 될 수 없다.","w":"압수물 환부는 형사소송법에 따른 형사절차에서 다룰 사항이다. 이에 대한 검사의 부작위는 행정소송의 대상이 아니라는 것이 판례다.","c":"중"},"세무사2025_62-73-2":{"f":"당사자의 신청에 대한 행정청의 거부처분은 부작위위법확인소송의 대상이 되지 않는다.","w":"거부처분은 처분이므로 취소소송이나 무효등 확인소송으로 다툰다. 부작위위법확인소송은 처분을 하지 않은 상태를 대상으로 한다.","c":"상"},"세무사2025_62-73-4":{"f":"부작위위법확인소송을 당사자소송으로 변경하는 것은 허용된다.","w":"부작위위법확인소송을 당사자소송으로 변경할 수 있다. 소의 변경에 관한 규정(제21조)이 준용된다. 행정소송법 제37조.","c":"상"},"세무사2025_62-73-5":{"f":"부작위위법확인소송에서는 취소소송에 있어서의 집행정지제도가 준용되지 않는다.","w":"집행정지(제23조)는 처분의 효력을 정지하는 제도로 처분이 없는 부작위에는 정지 대상이 없다. 부작위위법확인소송에는 준용되지 않는다. 행정소송법 제38조 제2항.","c":"상"},"세무사2025_62-74-4":{"f":"부작위위법확인판결에 대해서도 간접강제 규정이 준용된다.","w":"간접강제(제34조)는 거부처분취소소송과 부작위위법확인소송에 준용된다. 행정소송법 제38조 제2항.","c":"상"},"세무사2026_63-41-4":{"f":"처분에 대한 무효확인과 취소청구는 주위적ㆍ예비적 청구로서만 병합할 수 있고 선택적 병합은 허용되지 않는다.","w":"무효확인과 취소청구는 서로 양립할 수 없는 관계이므로 주위적ㆍ예비적 병합만 허용되고 선택적 병합은 허용되지 않는다는 것이 판례다.","c":"상"},"세무사2026_63-71-1":{"f":"작위의무확인을 구하는 소송은 무효등확인소송으로서 인정되지 않는다.","w":"행정청에 일정한 작위의무가 있음을 확인하는 소송은 행정소송법이 정하지 않은 소송유형이어서 허용되지 않는다.","c":"상"},"세무사2026_63-71-2":{"f":"행정심판을 거친 경우에도 제소기간을 준수할 필요가 없다.","w":"무효등 확인소송에는 제소기간 규정이 준용되지 않아 행정심판을 거쳤는지와 관계없이 제소기간 제한이 없다. 행정소송법 제38조 제1항.","c":"상"},"세무사2026_63-71-3":{"f":"무효등확인소송에는 보충성이 요구되지 않으므로 행정처분의 유ㆍ무효를 전제로 한 이행소송 등과 같은 직접적인 구제수단이 있는지 여부를 따질 필요가 없다.","w":"대법원 전원합의체 판결로 무효등 확인소송에는 보충성이 요구되지 않는다고 정리되었다.","c":"상"},"세무사2026_63-71-5":{"f":"거부처분에 대해 무효확인판결이 내려진 경우에는 행정청은 판결의 취지에 따라 재처분할 의무가 인정될 뿐 그에 대한 간접강제는 허용되지 않는다.","w":"무효확인판결에는 기속력에 따른 재처분의무가 있지만, 간접강제는 취소판결과 부작위위법확인판결에만 준용되어 무효확인판결에는 허용되지 않는다.","c":"상"},"세무사2026_63-75-4":{"f":"취소소송에 관한 규정 중 관련청구소송의 이송ㆍ병합에 관한 규정은 준용된다.","w":"관련청구소송의 이송ㆍ병합 규정(제10조)은 무효등 확인소송과 부작위위법확인소송에도 준용된다. 행정소송법 제38조.","c":"상"},"세무사2026_63-76-4":{"f":"당사자소송을 부작위위법확인소송으로 변경하는 것은 허용된다.","w":"소의 변경에 관한 규정(제21조)이 당사자소송에도 준용되어 당사자소송을 항고소송으로 변경할 수 있다. 행정소송법 제42조.","c":"중"},"세무사2016_53-48-5":{"f":"과세원인이 되는 기초사실이 같은 객관적 사실관계에 관하여 과세요건의 구성과 법적 평가만을 달리하는 처분사유의 추가는 허용된다.","w":"처분사유의 추가ㆍ변경은 당초 처분사유와 기본적 사실관계의 동일성이 인정되는 범위에서 허용된다. 사실관계가 같고 법적 평가만 다른 추가는 동일성이 유지되므로 허용된다.","c":"상"},"세무사2016_53-50-1":{"f":"변론주의가 원칙이고, 직권탐지주의가 가미되어 있다.","w":"행정소송은 변론주의를 기본 구조로 하면서 법원이 필요하면 직권으로 증거조사를 하고 당사자가 주장하지 않은 사실도 판단할 수 있도록 직권주의를 보충한다. 행정소송법 제26조.","c":"상"},"세무사2016_53-50-2":{"f":"법원이 당사자에게 새로운 청구를 할 것을 권유하는 것은 석명권의 한계를 넘어서는 것이다.","w":"석명권은 당사자 진술의 모순ㆍ불명확을 밝히거나 입증을 촉구하는 범위에서 행사한다. 법원이 새로운 청구를 권유하는 것은 그 한계를 넘는다.","c":"상"},"세무사2016_53-50-4":{"f":"법원은 행정소송에 있어서 원고의 청구범위를 초월하여 그 이상의 청구를 인용할 수 없다.","w":"행정소송에도 불고불리의 원칙(처분권주의)이 적용되어 법원은 원고의 청구범위를 넘어서 판결할 수 없다.","c":"상"},"세무사2016_53-50-5":{"f":"법원은 필요하다고 인정할 때에는 당사자가 주장하지 아니한 사실에 대하여도 판단할 수 있다.","w":"법원은 필요하다고 인정할 때 직권으로 증거조사를 하고, 당사자가 주장하지 않은 사실도 판단할 수 있다. 행정소송법 제26조.","c":"상"},"세무사2017_54-54-5":{"f":"집행정지결정의 효력은 정지결정의 대상인 처분의 발령시점에 소급하지 않는다.","w":"집행정지결정은 장래를 향해서만 효력이 있으며 처분이 발령된 때로 소급하지 않는다.","c":"상"},"세무사2017_54-65-2":{"f":"자유심증주의가 인정된다.","w":"행정소송에서도 증거의 가치는 법관이 자유로운 심증으로 판단하는 자유심증주의가 적용된다. 민사소송법이 준용된다.","c":"상"},"세무사2017_54-65-3":{"f":"구두변론주의를 원칙으로 한다.","w":"행정소송은 당사자의 구술 변론을 바탕으로 심리하는 구두변론주의를 원칙으로 한다. 서면심리주의는 원칙이 아니다.","c":"상"},"세무사2017_54-65-4":{"f":"법원이 소송절차를 직권으로 진행시키는 직권진행주의가 인정된다.","w":"소송절차의 진행은 당사자 신청이 아니라 법원이 직권으로 하는 직권진행주의가 적용된다.","c":"상"},"세무사2017_54-65-5":{"f":"공개주의가 원칙적으로 인정된다.","w":"재판의 심리와 판결은 공개하는 것이 원칙이다. 헌법 제109조.","c":"상"},"세무사2017_54-69-2":{"f":"법원은 당사자의 신청이 있는 때에 제출을 명할 수 있다.","w":"행정심판기록의 제출명령은 당사자의 신청이 있는 경우에 법원이 결정으로 한다. 직권으로 명할 수 있는 것이 아니다. 행정소송법 제25조 제1항.","c":"상"},"세무사2017_54-71-3":{"f":"취소소송에서 사정판결을 할 것인지의 여부는 심리의 대상에 포함된다.","w":"사정판결의 요건인 처분의 위법과 공공복리 적합 여부는 법원의 심리 대상이다. 당사자의 주장이 없어도 직권으로 판단할 수 있다.","c":"상"},"세무사2017_54-73-5":{"f":"처분의 사실관계에 변경이 없는 경우, 처분의 근거법령만을 변경하는 것은 허용된다.","w":"처분의 기본적 사실관계가 같다면 적용법령을 추가하거나 변경하는 것은 처분사유의 추가ㆍ변경 중에서도 허용되는 경우이다.","c":"상"},"세무사2017_54-75-5":{"f":"처분청의 처분권한 유무는 직권조사사항이 아니다.","w":"직권조사사항은 제소기간, 원고적격, 대상적격과 같은 소송요건이다. 처분청에게 권한이 있는지는 처분의 적법 요건이어서 본안에서 당사자가 주장하는 사항이다.","c":"중"},"세무사2017_54-77-4":{"f":"정보공개거부처분 취소소송에서 비공개사유의 주장ㆍ입증책임은 피고에게 있다.","w":"정보공개법은 공개가 원칙이므로 비공개사유가 있다는 주장과 입증책임은 피고인 공공기관에 있다.","c":"상"},"세무사2021_58-62-4":{"f":"","w":"원문만으로는 틀린 곳을 특정하기 어렵다. 법원은 처분이 위법할 때 취소하는 것이 원칙이지만, 사정판결이 가능한 경우에는 취소하지 않고 청구를 기각할 수 있다. 단순히 부당한 처분은 법원이 취소할 수 없다.","c":"하"},"세무사2021_58-71-2":{"f":"법원은 2021. 5. 24. 당시의 법령과 사실상태를 기준으로 하여 처분의 위법 여부를 판단하여야 한다.","w":"취소소송에서 처분의 위법 여부는 처분이 있었던 때(2021. 5. 24.)의 법령과 사실상태를 기준으로 판단한다. 판결 선고 시점은 기준이 아니다.","c":"상"},"세무사2021_58-71-3":{"f":"법원은 2021. 5. 24. 당시의 법령과 사실상태를 기준으로 하여 처분의 위법 여부를 판단하여야 한다.","w":"변론종결일의 법령과 사실상태가 아니라 처분 당시(2021. 5. 24.)를 기준으로 위법 여부를 판단한다.","c":"상"},"세무사2021_58-71-4":{"f":"법원은 변론종결 시까지 제출된 모든 자료를 종합하여 2021. 5. 24. 당시 존재하였던 객관적 사실을 확정하고 그 사실에 기초하여 처분의 위법 여부를 판단하여야 한다.","w":"위법 여부 판단의 기준시는 처분시이지만, 판단 자료는 처분 당시에 있었던 자료나 행정청에 제출된 자료에 한정되지 않고 사실심 변론종결 시까지 제출된 모든 자료이다.","c":"상"},"세무사2021_58-73-4":{"f":"부당해고 등의 구제신청에 관한 중앙노동위원회의 재심판정 취소소송에서 법원은 중앙노동위원회가 재심판정에서 인정한 징계사유에 한하지 않고 심리할 수 있다.","w":"재심판정 취소소송에서는 당사자가 재심판정에서 판단되지 않은 징계사유도 주장ㆍ증명할 수 있으므로 법원의 심리가 재심판정의 징계사유로 한정되지 않는다.","c":"중"},"세무사2021_58-79-2":{"f":"공무원에 대한 징계처분에는 공무원 승진임용처분에서와 같은 정도의 광범위한 재량이 부여되어 있지 않다.","w":"승진임용은 임용권자에게 광범위한 재량이 있는 반면, 징계처분은 재량이 있더라도 징계사유와 양정이 균형을 이루어야 하는 등 재량권 한계 안에서만 허용된다.","c":"중"},"세무사2022_59-69-1":{"f":"그 허용 기준이 되는 처분사유의 동일성 유무는 법적으로 평가할 때 동일한지 여부가 아니라 기본적 사실관계의 동일성 여부에 따라 결정된다.","w":"처분사유의 추가ㆍ변경은 당초 처분사유와 기본적 사실관계가 동일한 경우에만 허용된다. 기본적 사실관계 동일성은 처분의 사회적 사실관계를 기준으로 하며, 법률적 평가가 같은지로 정하지 않는다.","c":"상"},"세무사2022_59-70-5":{"f":"불고불리의 원칙이 적용되므로 법원은 당사자가 청구한 범위를 넘어서까지 판결을 할 수 없다.","w":"행정소송에도 처분권주의가 적용되어 법원은 원고가 청구하지 않은 사항에 대해 판결할 수 없다.","c":"상"},"세무사2022_59-79-2":{"f":"거부처분 취소소송에서 그 처분사유에 관한 증명책임은 피고에게 있다.","w":"취소소송에서 처분의 적법성에 대한 증명책임은 원칙적으로 처분청인 피고에게 있다. 거부처분도 같다.","c":"상"},"세무사2023_60-57-4":{"f":"법원은 사실심 변론종결 시까지 제출된 모든 자료를 종합하여 처분 당시 존재한 객관적 사실을 확정하고 위법 여부를 판단할 수 있다.","w":"위법 판단의 자료는 처분 당시 존재하였던 자료나 행정청에 제출되었던 자료로 한정되지 않는다. 변론종결 시까지 제출된 모든 자료를 쓴다.","c":"상"},"세무사2023_60-58-1":{"f":"행정소송법상 명문의 근거규정이 존재하지 않는다.","w":"처분사유의 추가ㆍ변경은 행정소송법에 규정이 없고 판례가 인정하는 법리이다.","c":"상"},"세무사2023_60-59-3":{"f":"행정처분의 당연무효를 주장하여 그 무효확인을 구하는 행정소송에 있어서는 원고에게 그 행정처분이 무효인 사유를 입증할 책임이 있다.","w":"무효확인소송에서는 무효 사유(하자가 중대ㆍ명백하다는 점)를 원고가 주장ㆍ증명해야 한다. 이는 취소소송에서 처분의 적법성을 피고가 증명하는 것과 다르다.","c":"상"},"세무사2024_61-41-1":{"f":"법원은 당사자가 주장하지 아니한 법률효과에 관한 요건사실이나 독립된 공격방어방법을 시사하여 그 제출을 권유할 수 없다.","w":"석명권은 당사자가 이미 주장한 것을 보완ㆍ정리하게 하는 범위에서만 행사할 수 있다. 주장하지 않은 요건사실이나 공격방어방법을 시사하는 것은 석명권의 한계를 넘는다.","c":"상"},"세무사2024_61-42-4":{"f":"乙은 소송계속 중 ‘甲이 계약의 이행과 관련하여 공무원에게 뇌물을 주었다’는 사실을 처분사유로 추가할 수 없다.","w":"뇌물을 준 사실은 당초 처분사유인 정당한 이유 없이 계약을 이행하지 않은 사실과 기본적 사실관계의 동일성이 없어 처분사유로 추가할 수 없다는 것이 판례다.","c":"상"},"세무사2024_61-43-1":{"f":"처분 후 법령의 개정이 있었더라도 처분시의 법령을 기준으로 처분의 위법을 판단해야 한다.","w":"항고소송에서 처분의 위법 여부는 처분이 있을 때의 법령과 사실상태를 기준으로 판단하며, 처분 후의 법령 개폐나 사실상태 변동에 영향을 받지 않는다.","c":"상"},"세무사2024_61-43-3":{"f":"거부처분 취소소송에서 위법판단의 기준시는 처분시이다.","w":"거부처분도 취소소송이므로 위법 여부는 처분시를 기준으로 판단한다. 판결시가 아니다.","c":"상"},"세무사2024_61-43-4":{"f":"행정심판의 재결을 거친 부작위위법확인소송에서 위법판단의 기준시는 판결시(사실심 변론종결시)이다.","w":"부작위위법확인소송은 처분이 없어 처분시라는 기준이 없다. 위법 여부는 사실심 변론종결 시를 기준으로 판단하며, 재결을 거쳤는지와는 관계없다.","c":"상"},"세무사2024_61-43-5":{"f":"계속효가 있는 처분에 대한 취소소송의 경우에도 처분시를 기준으로 한다.","w":"계속효 있는 처분도 취소소송의 위법 판단 기준은 처분시다. 처분 후에 생긴 사정은 처분의 위법 여부에 영향을 주지 않는다.","c":"중"},"세무사2024_61-44-3":{"f":"원고는 전심절차에서 주장하지 아니한 공격방어방법을 소송절차에서 주장할 수 있다.","w":"전심절차에서 주장한 내용과 소송에서의 주장이 반드시 일치할 필요는 없으며, 전심에서 주장하지 않은 공격방어방법도 소송에서 주장할 수 있다.","c":"상"},"세무사2025_62-64-4":{"f":"행정청의 처분사유의 추가ㆍ변경은 사실심 변론종결 시까지 허용된다.","w":"처분사유의 추가ㆍ변경은 기본적 사실관계의 동일성이 있는 범위에서 사실심 변론종결 시까지 할 수 있다. 사실심 개시 전으로 제한되지 않는다.","c":"상"},"세무사2026_63-62-2":{"f":"소송계속중 심사청구 및 심판청구를 하여 원심변론종결일까지 각 기각결정을 받았다면 전치요건흠결의 하자가 치유되었다고 할 수 있다.","w":"행정심판 전치요건이 소제기 시에 흠결되어 있어도 사실심 변론종결 시까지 갖추면 하자가 치유된다는 것이 판례다.","c":"중"},"세무사2026_63-63-4":{"f":"특허심판원 심결취소소송에서 당사자가 주장하지 않은 사유에 기초하여 처분에 무효 사유가 있다고 본 판결은 위법하다.","w":"변론주의에 따라 법원은 당사자가 주장하지 않은 사유로 판단할 수 없다. 당사자가 주장하지 않은 사유로 심결의 위법을 판단하면 변론주의 위반이다.","c":"중"},"세무사2026_63-64-1":{"f":"법원은 원고의 청구범위를 초월하여 그 이상의 청구를 인용할 수 없다.","w":"행정소송에도 불고불리의 원칙이 적용되어, 법원은 필요하다고 인정하더라도 원고의 청구범위를 넘어 인용할 수 없다.","c":"상"},"세무사2016_53-49-1":{"f":"다른 법률에 특별한 규정이 없는 한 국가ㆍ공공단체 그 밖의 권리주체를 피고로 한다.","w":"당사자소송의 피고는 처분을 한 행정청이 아니라 법률관계의 한쪽 당사자인 국가ㆍ공공단체 그 밖의 권리주체이다. 행정청이 피고가 되는 것은 항고소송이다. 행정소송법 제39조.","c":"상"},"세무사2016_53-69-1":{"f":"취소원인인 하자가 있는 처분의 효력을 다툴 수 없다.","w":"당사자소송에서는 취소사유에 불과한 하자가 있는 처분의 효력을 부정할 수 없다. 처분의 효력은 공정력 때문에 취소소송을 통해서만 배제할 수 있다.","c":"중"},"세무사2016_53-69-3":{"f":"처분으로 형성된 법률관계에 대하여도 허용된다.","w":"당사자소송은 행정청의 처분등을 원인으로 하는 법률관계에 관한 소송과 그 밖에 공법상 법률관계에 관한 소송 모두를 대상으로 한다. 행정소송법 제3조 제2호.","c":"상"},"세무사2016_53-69-4":{"f":"관련 민사소송을 병합할 수 있다.","w":"관련청구소송의 이송ㆍ병합(제10조)은 당사자소송에 준용되어, 관련 민사소송도 병합할 수 있다. 행정소송법 제44조 제2항.","c":"상"},"세무사2016_53-69-5":{"f":"확인소송뿐 아니라 이행소송도 허용된다.","w":"당사자소송은 공법상 법률관계에 관한 소송이므로 확인판결뿐 아니라 이행판결도 할 수 있다. 의무이행소송이 허용되지 않는 항고소송과 다르다.","c":"상"},"세무사2016_53-75-2":{"f":"민중소송은 국가 또는 공공단체의 기관이 법률에 위반되는 행위를 한 때에 직접 자기의 법률상 이익과 관계없이 그 시정을 구하기 위하여 제기하는 소송이다.","w":"민중소송은 자기의 법률상 이익과 관계없이 제기하는 객관소송이다. 법률상 이익이 있는 자가 제기하는 것은 항고소송이다. 행정소송법 제3조 제3호.","c":"상"},"세무사2016_53-75-3":{"f":"지방자치법상 주민소송은 민중소송에 해당한다.","w":"주민소송은 주민이 자기의 법률상 이익과 관계없이 위법한 재무회계 행위의 시정을 구하는 소송으로 민중소송이다.","c":"상"},"세무사2016_53-75-4":{"f":"민중소송에는 그 성질에 반하지 아니하는 한 취소소송에 관한 규정을 준용하며, 기관소송의 경우에도 그러하다.","w":"민중소송과 기관소송으로 처분등의 취소를 구하는 소송에는 모두 성질에 반하지 않는 한 취소소송 규정을 준용한다. 행정소송법 제46조 제1항.","c":"상"},"세무사2016_53-75-5":{"f":"기관소송은 헌법재판소법상 헌법재판소의 관장사항으로 되는 소송을 제외한다.","w":"기관소송은 국가 또는 공공단체의 기관 상호간의 권한 다툼 중 헌법재판소가 관장하는 권한쟁의심판은 제외한다. 행정소송법 제3조 제4호 단서.","c":"상"},"세무사2017_54-70-4":{"f":"","w":"원문만으로는 틀린 곳을 특정하기 어렵다. 판례는 항고소송의 대상이 아니라는 이유로 곧바로 각하하지 않고, 공법상 법률관계에 관한 소라면 당사자소송으로 변경하도록 석명해야 한다고 본다.","c":"하"},"세무사2021_58-42-5":{"f":"행정소송법에는 당사자소송에 관한 규정을 민중소송에 준용하는 조항이 있다.","w":"민중소송이나 기관소송으로서 취소ㆍ무효등 확인ㆍ부작위위법확인 소송 외의 소송에는 성질에 반하지 않는 한 당사자소송 규정을 준용한다. 행정소송법 제46조 제3항.","c":"상"},"세무사2021_58-43-2":{"f":"행정소송법은 국가를 상대로 하는 당사자소송의 경우에는 가집행선고를 할 수 없다고 규정하고 있었다.","w":"(2022.2.24 헌법재판소 위헌결정 전 기준. 구 행정소송법 제43조는 국가를 상대로 한 당사자소송에서 가집행선고를 할 수 없다고 정했으나 위헌결정으로 효력을 잃어 현행은 가집행선고가 가능하다.)","c":"중","old":1,"ow":"출제 당시 정답 X. 2022.2.24 헌법재판소 위헌결정(행정소송법 제43조)으로 지금은 국가를 상대로 한 당사자소송에서도 가집행선고를 할 수 있다."},"세무사2021_58-80-5":{"f":"수용재결취소소송과 보상금증액청구소송은 병합하여 제기할 수 있다.","w":"수용재결 취소소송은 항고소송, 보상금증액청구소송은 당사자소송이지만 서로 관련청구소송이므로 병합이 허용된다.","c":"중"},"세무사2022_59-43-1":{"f":"처분의 취소를 구하는 취지의 소송일지라도 취소소송에 관한 제소기간의 규정이 준용된다.","w":"민중소송이나 기관소송으로 처분의 취소를 구하는 경우 성질에 반하지 않는 한 제소기간을 포함한 취소소송의 규정이 준용된다. 행정소송법 제46조 제1항.","c":"중"},"세무사2022_59-43-2":{"f":"법률에 정한 경우에 법률에 정한 자에 한하여 제기할 수 있다.","w":"민중소송과 기관소송은 법률이 정한 경우에 법률에 정한 자만 제기할 수 있다. 정당한 이익이 있다고 해서 제기할 수 있는 것이 아니다. 행정소송법 제45조.","c":"상"},"세무사2022_59-43-3":{"f":"국가 또는 공공단체의 기관 상호간에 있어서의 권한의 존부 또는 그 행사에 관한 다툼이 있을 때 제기하는 소송이다.","w":"기관소송은 같은 국가나 공공단체에 속한 기관 사이의 권한 다툼이다. 국가기관과 지방자치단체 사이의 다툼은 기관소송이 아니라 헌법재판소의 권한쟁의심판이다.","c":"상"},"세무사2022_59-43-4":{"f":"공공단체의 기관이 법률에 위반되는 행위를 한 때에 직접 자기의 법률상 이익과 관계없이 그 시정을 구하기 위하여 제기하는 소송은 민중소송이다.","w":"자기의 법률상 이익과 관계없이 위법한 행위의 시정을 구하는 소송은 민중소송이다. 기관소송은 기관 상호간의 권한 다툼에 관한 소송이다.","c":"상"},"세무사2022_59-47-1":{"f":"민중소송은 객관적 소송이다.","w":"민중소송은 자기의 법률상 이익과 관계없이 법률 위반의 시정을 구하는 객관소송이다.","c":"상"},"세무사2022_59-47-3":{"f":"「지방자치법」상 주민소송은 민중소송에 해당한다.","w":"주민소송은 주민이 지방자치단체의 위법한 재무회계 행위의 시정을 구하는 소송으로 민중소송이다.","c":"상"},"세무사2022_59-47-4":{"f":"당사자소송에 관한 규정은 민중소송에 준용될 수 있다.","w":"민중소송으로서 취소ㆍ무효확인ㆍ부작위위법확인 소송 외의 소송에는 그 성질에 반하지 않는 한 당사자소송 규정을 준용한다. 행정소송법 제46조 제3항.","c":"상"},"세무사2022_59-47-5":{"f":"「공직선거법」 제222조의 선거소송은 민중소송에 해당한다.","w":"선거소송은 선거인이 법률상 이익과 관계없이 선거의 효력을 다투는 소송이므로 민중소송이다.","c":"상"},"세무사2022_59-66-1":{"f":"당사자소송의 피고는 국가ㆍ공공단체 그 밖의 권리주체가 된다.","w":"당사자소송은 법률관계의 한쪽 당사자를 피고로 하므로 행정청이 아니라 권리주체인 국가ㆍ공공단체 등이 피고이다. 행정소송법 제39조.","c":"상"},"세무사2022_59-66-3":{"f":"당사자소송에 대하여는 민사집행법상 가처분에 관한 규정이 준용된다.","w":"당사자소송에는 집행정지 규정이 없고, 판례는 민사집행법상 가처분 규정이 준용된다고 본다.","c":"중"},"세무사2022_59-66-4":{"f":"사인을 피고로 하는 당사자소송도 허용된다.","w":"당사자소송의 피고는 국가ㆍ공공단체 그 밖의 권리주체이므로 공무수탁사인이나 사인도 피고가 될 수 있다.","c":"상"},"세무사2022_59-66-5":{"f":"토지수용재결이 있은 후 토지소유자가 사업시행자를 피고로 하여 제기하는 보상금증액청구소송은 당사자소송이다.","w":"토지보상법상 보상금증액청구소송은 토지소유자가 사업시행자를 피고로 제기하는 형식적 당사자소송이다.","c":"상"},"세무사2023_60-53-1":{"f":"충청남도와 세종특별자치시 간의 권한쟁의심판은 행정소송법상 기관소송에 해당하지 않는다.","w":"지방자치단체 상호간 권한 다툼은 헌법재판소의 권한쟁의심판 사항이다. 행정소송법상 기관소송에서는 헌법재판소 관장 사항이 제외된다.","c":"상"},"세무사2023_60-68-3":{"f":"공무수탁사인도 당사자소송의 피고가 될 수 있다.","w":"당사자소송의 피고는 국가ㆍ공공단체 그 밖의 권리주체이므로 공무수탁사인도 피고가 될 수 있다.","c":"중"},"세무사2023_60-73-1":{"f":"위법행정의 시정을 구하는 자라도 법률이 정한 경우에 법률에 정한 자에 한하여 민중소송을 제기할 수 있다.","w":"민중소송은 개별 법률의 근거가 있는 경우에만 법률이 정한 자가 제기할 수 있다. 행정소송법이 일반적으로 인정하지 않는다. 행정소송법 제45조.","c":"상"},"세무사2023_60-73-2":{"f":"자기의 법률상 이익과 관계없이 법률에 정한 자가 제기할 수 있다.","w":"민중소송은 법률상 이익이 있는 자가 제기하는 소송이 아니고, 자기의 법률상 이익과 관계없이 법률이 정한 자가 제기한다.","c":"상"},"세무사2023_60-73-3":{"f":"「지방자치법」상 지방의회재의결에 대한 지방자치단체장의 소송은 기관소송이다.","w":"지방자치단체장이 지방의회의 재의결에 대해 대법원에 제기하는 소송은 기관 상호 간의 다툼이므로 기관소송이다.","c":"상"},"세무사2023_60-73-4":{"f":"취소소송에 관한 규정이 성질에 반하지 아니하는 한 준용된다.","w":"민중소송으로 처분등의 취소를 구하는 경우 취소소송 규정이 준용된다. 행정소송법 제46조 제1항.","c":"상"},"세무사2024_61-55-1":{"f":"사인을 피고로 하는 당사자소송도 허용된다.","w":"당사자소송의 피고는 국가ㆍ공공단체 그 밖의 권리주체로 사인이 상대방이 될 수 있다. 지방자치단체가 사인을 피고로 제기하는 경우도 가능하다.","c":"상"},"세무사2024_61-55-2":{"f":"부가가치세 환급세액의 지급청구는 국가를 피고로 하여 당사자소송으로 하여야 한다.","w":"부가가치세 환급세액 지급청구는 공법상 당사자소송이고, 당사자소송의 피고는 행정청이 아니라 국가 등 권리주체이다.","c":"중"},"세무사2024_61-55-3":{"f":"당사자소송과 관련청구소송이 각각 다른 법원에 계속되고 있는 경우 법원은 당사자의 신청 또는 직권으로 관련청구소송을 이송할 수 있다.","w":"관련청구소송의 이송은 당사자의 신청이나 법원의 직권으로 할 수 있다. 행정소송법 제44조 제2항, 제10조 제1항.","c":"상"},"세무사2024_61-55-5":{"f":"회복하기 어려운 손해를 예방하기 위하여 긴급한 필요가 있는 경우에도 당사자소송에서는 집행정지를 신청할 수 없다.","w":"집행정지는 처분등의 효력이나 집행을 정지하는 제도이므로 처분이 대상이 아닌 당사자소송에는 준용되지 않는다. 다만 민사집행법상 가처분이 준용될 수 있다.","c":"상"},"세무사2025_62-77-1":{"f":"「행정소송법」에는 당사자소송의 원고적격에 관한 직접적인 규정이 없다.","w":"행정소송법에는 당사자소송의 원고적격을 정한 규정이 없다. 민사소송처럼 권리 주장자가 원고가 된다.","c":"상"},"세무사2025_62-77-2":{"f":"당사자소송에서는 국가ㆍ공공단체 그 밖의 권리주체가 피고가 된다.","w":"당사자소송의 피고는 처분청인 행정청이 아니라 법률관계의 한쪽 당사자인 권리주체이다. 행정소송법 제39조.","c":"상"},"세무사2025_62-77-4":{"f":"당사자소송에서도 피고경정이 인정된다.","w":"피고경정에 관한 제14조는 당사자소송에 준용된다. 피고를 잘못 지정한 경우 법원은 석명권을 행사해 정당한 피고로 경정하게 해야 한다. 행정소송법 제44조 제1항.","c":"상"},"세무사2025_62-77-5":{"f":"당사자소송의 확정판결은 제3자에 대하여는 효력이 없다.","w":"취소판결의 제3자효(제29조)는 당사자소송에 준용되지 않는다. 당사자소송에는 기속력(제30조 제1항)만 준용된다. 행정소송법 제44조 제1항.","c":"중"},"세무사2025_62-78-4":{"f":"「공직선거법」 제222조의 선거소송은 당해 선거구선거관리위원회위원장을 피고로 하여 대법원 또는 고등법원에 제기하는 소송이다.","w":"선거소송은 선거의 종류에 따라 대법원 또는 고등법원이 관할하며, 피고는 선거관리위원회위원장이다. 행정법원의 사건이 아니다. 공직선거법 제222조.","c":"중"},"세무사2025_62-79-1":{"f":"기관소송은 객관적 소송이다.","w":"기관소송은 국가 또는 공공단체의 기관 상호간의 권한 다툼으로 법률이 정한 경우에만 허용되는 객관소송이다. 권리 구제를 위한 주관소송이 아니다.","c":"상"},"세무사2025_62-79-2":{"f":"기관소송으로 처분의 부작위의 위법의 확인을 구하는 소송에는 성질에 반하지 아니하는 한 부작위위법확인소송에 관한 규정이 준용된다.","w":"기관소송과 민중소송으로 부작위위법확인을 구하는 경우에는 부작위위법확인소송의 규정을 준용한다. 행정소송법 제46조 제2항.","c":"상"},"세무사2025_62-79-3":{"f":"「헌법재판소법」 제2조의 규정에 의하여 헌법재판소의 관장사항으로 되는 소송은 기관소송에서 제외된다.","w":"기관소송에서 헌법재판소가 관장하는 권한쟁의심판은 제외된다. 행정소송법 제3조 제4호 단서.","c":"상"},"세무사2025_62-79-4":{"f":"지방자치단체의 장이 지방의회의 재의결에 대하여 대법원에 제기하는 소송은 기관소송에 해당한다.","w":"지방자치법에 따라 단체장이 지방의회의 재의결을 대법원에 제소하는 것은 기관 상호간의 권한 다툼으로 기관소송이다.","c":"상"},"세무사2026_63-70-1":{"f":"국민 개인의 주관적 법적 이익을 구제하기 위한 소송이 아니다.","w":"민중소송은 자기의 법률상 이익과 관계없이 법률 위반의 시정을 구하는 객관소송이다.","c":"상"},"세무사2026_63-70-2":{"f":"「지방자치법」상 지방의회재의결에 대한 지방자치단체장의 소송은 기관소송에 해당한다.","w":"지방자치단체장이 지방의회의 재의결을 대법원에 제소하는 소송은 기관소송이다. 민중소송은 법률상 이익과 관계없이 일반 주민이 제기하는 경우다.","c":"상"},"세무사2026_63-70-3":{"f":"부작위위법확인소송에 관한 규정은 민중소송에 준용될 수 있다.","w":"민중소송으로 부작위위법 확인을 구하는 경우 성질에 반하지 않는 한 부작위위법확인소송 규정을 준용한다. 행정소송법 제46조 제2항.","c":"상"},"세무사2026_63-70-4":{"f":"당사자소송에 관한 규정은 민중소송에 준용될 수 있다.","w":"취소ㆍ무효확인ㆍ부작위위법확인 소송 외의 민중소송에는 성질에 반하지 않는 한 당사자소송 규정을 준용한다. 행정소송법 제46조 제3항.","c":"상"},"세무사2026_63-73-1":{"f":"공공단체가 피고인 경우에는 관계 행정청의 소재지를 피고의 소재지로 본다.","w":"국가 또는 공공단체가 피고인 당사자소송에서는 관계 행정청의 소재지를 피고의 소재지로 보아 관할을 정한다. 행정소송법 제40조.","c":"중"},"세무사2026_63-73-3":{"f":"취소소송의 소송비용에 관한 규정은 당사자소송에 준용된다.","w":"소송비용의 부담(제32조)과 소송비용 재판의 효력(제33조)은 당사자소송에 준용된다. 행정소송법 제44조 제1항.","c":"상"},"세무사2026_63-73-4":{"f":"납세의무부존재확인의 소의 피고는 과세관청이 아닌 국가이다.","w":"납세의무부존재확인소송은 당사자소송이고, 피고는 국가 또는 공공단체이다. 과세관청인 세무서장을 피고로 하면 법원은 피고의 경정을 허가할 수 있다.","c":"중"},"세무사2026_63-73-5":{"f":"구 「도시 및 주거환경정비법」상 재개발조합과 조합장 사이의 선임ㆍ해임을 둘러싼 법률관계에 관한 소송은 민사소송에 의하여야 한다.","w":"재개발조합은 공법인이지만 조합과 조합장 사이의 선임ㆍ해임 관계는 사법상 법률관계로 보아 민사소송으로 다툰다는 것이 판례다.","c":"중"},"세무사2026_63-77-1":{"f":"개인의 권익보호가 아니라 법규의 적정한 적용을 확보하기 위한 객관적 소송이다.","w":"민중소송과 기관소송은 개인의 권리구제가 아닌 객관적 법질서 유지를 위한 객관소송이다.","c":"중"},"세무사2026_63-80-1":{"f":"소송의 대상이 공법상 법률관계라는 점에서 민사소송과 구분된다.","w":"당사자소송은 처분이 아니라 공법상 법률관계 자체를 대상으로 하는 점에서 민사소송과 구별된다. 처분을 대상으로 하는 것은 항고소송이다.","c":"상"},"세무사2026_63-80-2":{"f":"「부가가치세법」 제59조에 따른 환급청구는 당사자소송에 의할 수 있다.","w":"부가가치세 환급세액 지급청구는 공법상 당사자소송으로 한다는 것이 전원합의체 판결이다.","c":"중"},"세무사2026_63-80-3":{"f":"명예퇴직한 법관이 미지급 명예퇴직수당액의 지급을 청구하는 소송은 당사자소송에 의하여야 한다.","w":"명예퇴직수당은 공법상 법률관계에 기한 금전지급청구이므로 민사소송이 아니라 공법상 당사자소송에 의한다는 것이 판례다.","c":"중"},"세무사2026_63-80-5":{"f":"계약직 시립합창단원의 재위촉거부를 다투는 소송은 당사자소송에 의하여야 한다.","w":"시립합창단원의 위촉은 공법상 근무관계이고 재위촉 거부는 처분이 아니라는 것이 판례이다. 따라서 항고소송이 아니라 당사자소송으로 다툰다.","c":"중"},"세무사2016_53-54-1":{"f":"원상회복청구소송은 당해 처분등과 관련되는 경우에는 관련청구소송에 해당된다.","w":"관련청구소송에는 당해 처분과 관련되는 손해배상, 부당이득반환, 원상회복 등 청구소송이 포함된다. 행정소송법 제10조 제1항 제1호.","c":"상"},"세무사2016_53-54-2":{"f":"관련청구소송의 병합은 사실심변론종결 시까지 가능하다.","w":"관련청구소송의 병합은 사실심 변론종결 전까지만 할 수 있다. 변론종결 후에는 병합할 수 없다. 행정소송법 제10조 제2항.","c":"상"},"세무사2016_53-54-4":{"f":"처분의 취소소송에는 처분과 관련된 부당이득반환청구소송을 취소소송이 계속된 법원에 병합하여 제기할 수 있다.","w":"병합은 의무가 아니고, 취소소송이 계속된 법원에 관련청구소송을 병합해 제기할 수 있다는 규정이다. 행정소송법 제10조 제2항.","c":"상"},"세무사2016_53-54-5":{"f":"취소소송의 소송요건이 갖추어졌더라도 관련청구소송도 소송요건을 갖추어야 한다.","w":"관련청구소송을 병합하려면 그 소송 자체도 소송요건을 갖추어야 한다. 본래의 취소소송이 부적법하면 병합된 관련청구도 함께 각하된다.","c":"상"},"세무사2016_53-56-3":{"f":"검사의 불기소처분은 항고소송으로 다툴 수 없다.","w":"검사의 불기소처분은 형사소송법상 재정신청이나 헌법소원으로 다투며 항고소송의 대상이 아니다.","c":"상"},"세무사2016_53-57-4":{"f":"조례가 항고소송의 대상이 되는 경우 조례를 공포한 지방자치단체장이 피고가 된다.","w":"조례의 공포 권한은 지방자치단체장에게 있어 처분청은 단체장이다. 지방의회는 피고가 되지 않는다. 교육 조례는 교육감이 피고이다.","c":"상"},"세무사2016_53-64-5":{"f":"처분의 변경으로 인한 소변경이 있으면 종전의 소는 취하된 것으로 본다.","w":"처분변경으로 소가 변경되면 종전의 소는 취하된 것으로 본다. 기각된 것으로 보지 않는다. 행정소송법 제22조 제3항, 제21조 제4항.","c":"중"},"세무사2016_53-76-3":{"f":"법원이 제3자의 소송참가를 결정할 때에는 미리 당사자 및 제3자의 의견을 들어야 한다.","w":"제3자 소송참가 결정에는 당사자와 제3자의 의견을 듣는 절차가 필요하지만, 당사자의 동의를 얻을 필요는 없다. 행정소송법 제16조 제2항.","c":"상"},"세무사2017_54-51-4":{"f":"합의제 행정청인 중앙노동위원회의 처분에 대한 소송의 피고는 중앙노동위원회위원장이 된다.","w":"노동위원회법은 중앙노동위원회의 처분에 대한 행정소송의 피고를 위원장으로 정한다. 일반 합의제 행정청은 해당 행정청 자체가 피고인 것과 다르다.","c":"상"},"세무사2017_54-53-4":{"f":"소의 변경을 허가하는 결정이 확정되면 새로운 소는 제소기간과 관련하여 원칙적으로 처음 소를 제기한 때에 제기된 것으로 본다.","w":"소의 종류를 변경하면 변경된 소는 처음 소를 제기한 때에 제기된 것으로 보아 제소기간을 판단한다. 행정소송법 제21조 제4항, 제14조 제4항.","c":"상"},"세무사2017_54-56-1":{"f":"제3자의 소송참가를 위해 요구되는 이익에는 단순한 경제상의 이익은 포함되지 않는다.","w":"소송참가의 이익은 소송 결과에 따라 권리 또는 이익의 침해를 받는 법률상의 이익이다. 사실상ㆍ경제상 이해관계만으로는 참가할 수 없다. 행정소송법 제16조 제1항.","c":"상"},"세무사2017_54-56-2":{"f":"제3자의 소송참가에서 제3자에는 국가 또는 지방자치단체도 포함된다.","w":"제3자 소송참가의 제3자에는 개인뿐 아니라 국가나 지방자치단체도 포함된다.","c":"상"},"세무사2017_54-56-3":{"f":"부작위위법확인소송에서도 제3자의 소송참가가 허용된다.","w":"제3자의 소송참가(제16조)는 부작위위법확인소송과 무효등 확인소송에 준용된다. 행정소송법 제38조.","c":"상"},"세무사2017_54-56-5":{"f":"행정소송 사건에서 참가인이 한 보조참가는 「행정소송법」상 제3자의 소송참가에 해당하지 않더라도 「민사소송법」상 보조참가의 요건을 갖춘 경우에는 허용된다.","w":"행정소송 사건에서도 민사소송법상 보조참가 요건을 갖추면 보조참가가 허용된다는 것이 판례이다. 행정소송법 제8조 제2항.","c":"상"},"세무사2017_54-64-3":{"f":"법원은 관련청구소송의 이송을 당사자의 신청 또는 직권으로 할 수 있다.","w":"관련청구소송의 이송은 당사자의 신청이나 법원의 직권으로 할 수 있다. 행정소송법 제10조 제1항.","c":"상"},"세무사2017_54-79-1":{"f":"국가의 사무를 위탁받은 공공단체를 피고로 하는 경우, 대법원의 소재지를 관할하는 행정법원도 관할법원이다.","w":"중앙행정기관, 그 부속기관과 국가 사무를 위탁받은 공공단체를 피고로 하는 취소소송은 대법원 소재지를 관할하는 행정법원에도 제기할 수 있다. 행정소송법 제9조 제2항.","c":"상"},"세무사2021_58-55-4":{"f":"내부위임의 경우 처분권한이 이전되지 않으나, 수임기관이 자신의 이름으로 처분을 하였다면 수임기관이 피고가 된다.","w":"항고소송의 피고는 실제로 처분을 한 명의 행정청이다. 내부위임을 받은 수임기관이 자기 이름으로 처분하면 수임기관이 피고이고, 위임청이 아니다.","c":"상"},"세무사2021_58-56-1":{"f":"특허심판원의 심결에 불복하는 경우 그 취소를 구하는 소송은 특허법원에 제기하여야 한다.","w":"특허심판원의 심결에 대한 취소소송은 특허법원의 전속관할이다.","c":"상"},"세무사2021_58-56-2":{"f":"고의 또는 중과실 없이 행정소송으로 제기하여야 할 사건을 민사소송으로 잘못 제기한 경우, 나머지 소송요건을 모두 갖추었다면 법원은 관할법원에 이송하여야 한다.","w":"행정소송과 민사소송을 잘못 선택한 경우에도 원고의 고의 또는 중과실이 없으면 각하하지 않고 관할법원에 이송한다. 민사소송법 제34조 제1항.","c":"상"},"세무사2021_58-56-4":{"f":"국가의 사무를 위탁받은 공공단체를 피고로 하여 취소소송을 제기하는 경우 대법원소재지를 관할하는 행정법원에 제기하는 것은 관할 위반이 아니다.","w":"국가 사무를 위탁받은 공공단체가 피고인 취소소송은 대법원 소재지를 관할하는 행정법원에도 제기할 수 있다. 행정소송법 제9조 제2항.","c":"상"},"세무사2021_58-56-5":{"f":"항고소송을 제기할 것을 민사소송으로 잘못 제기한 경우 수소법원이 그 항고소송에 대한 관할도 동시에 가지고 있다면 행정소송으로 심리ㆍ판단하여야 한다.","w":"수소법원이 항고소송의 관할도 가지고 있다면 이송하지 않고 항고소송으로 보아 심리ㆍ판단해야 한다는 것이 판례이다.","c":"중"},"세무사2021_58-57-3":{"f":"행정청이 처분을 변경한 경우 법원은 원고의 신청에 의하여 결정으로 청구취지 또는 청구원인의 변경을 허가할 수 있다.","w":"처분변경으로 인한 소의 변경은 원고의 신청이 있어야 하고 법원이 직권으로 변경할 수 없다. 행정소송법 제22조 제1항.","c":"상"},"세무사2021_58-65-1":{"f":"처분변경으로 인한 소의 변경 신청은 처분이 변경되었음을 안 날로부터 60일 이내에 하여야 한다.","w":"기산점은 변경된 날이 아니라 변경이 있음을 안 날이다. 행정소송법 제22조 제2항.","c":"상"},"세무사2021_58-65-2":{"f":"항고소송에서 당사자소송으로 소의 종류를 변경함으로써 피고의 변경이 있는 경우 종전의 피고에 대한 소송은 취하된 것으로 본다.","w":"소의 변경으로 피고가 바뀌면 종전 피고에 대한 소송은 각하가 아니라 취하된 것으로 본다. 행정소송법 제21조 제4항, 제14조 제4항.","c":"상"},"세무사2021_58-65-3":{"f":"행정소송법이 정하는 소의 변경은 민사소송법상의 소의 변경을 배척하지 않는다.","w":"행정소송법에 규정이 없는 사항은 민사소송법을 준용하므로, 행정소송법상 소의 변경 외에 민사소송법상 소의 변경도 가능하다. 행정소송법 제8조 제2항.","c":"중"},"세무사2021_58-65-4":{"f":"청구의 원인을 변경하는 형태의 소의 변경도 허용된다.","w":"법원은 청구의 기초에 변경이 없는 한 청구의 취지 또는 원인의 변경을 허가할 수 있다. 행정소송법 제21조 제1항.","c":"상"},"세무사2021_58-69-1":{"f":"법원이 B행정청의 소송참가를 결정할 때에는 당사자 및 B행정청의 의견을 들어야 한다.","w":"다른 행정청의 소송참가를 결정할 때에는 당사자와 해당 행정청의 의견을 미리 들어야 한다. 행정소송법 제17조 제2항.","c":"상"},"세무사2021_58-69-3":{"f":"乙의 소송참가는 당사자나 乙의 신청 또는 법원의 직권에 의하여 할 수 있다.","w":"제3자의 소송참가는 당사자 또는 제3자의 신청이나 법원의 직권으로 결정한다. 제3자 본인도 신청할 수 있다. 행정소송법 제16조 제1항.","c":"상"},"세무사2021_58-69-4":{"f":"乙은 행정소송법상 제3자의 소송참가를 할 수 있을 뿐 아니라 민사소송법상 보조참가의 요건을 갖추었다면 민사소송법상 보조참가도 할 수 있다.","w":"행정소송에서도 민사소송법상 보조참가 요건을 갖추면 보조참가가 허용된다는 것이 판례이다.","c":"상"},"세무사2021_58-69-5":{"f":"乙을 소송에 참가시키는 법원의 결정이 있었다면 乙이 현실적으로 소송에 참가하여 소송행위를 하지 않았더라도 乙에게 판결의 효력이 미친다.","w":"취소판결은 소송참가 여부와 관계없이 제3자에게도 효력이 있다. 참가결정이 있었다면 더욱 효력이 미친다. 행정소송법 제29조 제1항.","c":"중"},"세무사2022_59-41-1":{"f":"공공단체의 기관은 법령에 의하여 행정권한의 위탁을 받은 경우에는 행정청에 포함된다.","w":"행정청에는 국가나 지방자치단체의 기관뿐 아니라 법령에 의해 행정권한을 위임 또는 위탁받은 공공단체와 그 기관, 사인도 포함된다. 행정소송법 제2조 제2항.","c":"상"},"세무사2022_59-41-2":{"f":"기관소송은 헌법재판소법 제2조의 규정에 의하여 헌법재판소의 관장사항으로 되는 소송을 제외한다.","w":"기관소송에서 헌법재판소가 관장하는 권한쟁의심판은 제외된다. 행정소송법 제3조 제4호 단서.","c":"상"},"세무사2022_59-41-4":{"f":"수인의 청구 또는 수인에 대한 청구가 처분등의 취소청구와 관련되는 청구인 경우에 한하여 그 수인은 취소소송의 공동소송인이 될 수 있다.","w":"취소소송의 공동소송은 청구들이 처분등의 취소청구와 관련되는 경우에 한해 허용된다. 행정소송법 제15조.","c":"상"},"세무사2022_59-41-5":{"f":"행정청의 재량에 속하는 처분이라도 재량권의 한계를 넘거나 그 남용이 있는 때에는 법원은 이를 취소할 수 있다.","w":"재량처분도 재량권의 일탈ㆍ남용이 있으면 위법하여 법원이 취소할 수 있다. 행정소송법 제27조.","c":"상"},"세무사2022_59-50-3":{"f":"취소소송의 제1심관할법원은 피고의 소재지를 관할하는 행정법원으로 한다.","w":"취소소송의 제1심 관할법원은 피고의 소재지를 관할하는 행정법원이다. 원고의 소재지가 아니다. 행정소송법 제9조 제1항.","c":"상"},"세무사2022_59-55-2":{"f":"무효등 확인소송이나 부작위위법확인소송을 취소소송 또는 당사자소송으로 변경할 수 있다.","w":"소의 변경(제21조)은 무효등 확인소송과 부작위위법확인소송에도 준용되어 취소소송이나 당사자소송으로 변경할 수 있다. 행정소송법 제37조, 제38조.","c":"상"},"세무사2022_59-62-4":{"f":"법원은 원고의 신청이 있어야 소의 변경을 결정할 수 있다.","w":"소의 변경은 원고의 신청에 따라 법원이 결정으로 허가한다. 직권으로 소를 변경할 수 없다. 행정소송법 제21조.","c":"상"},"세무사2022_59-64-4":{"f":"사인도 법령에 의하여 행정권한의 위탁을 받은 경우에는 취소소송의 피고가 될 수 있다.","w":"법령에 의해 행정권한을 위탁받은 사인은 행정청에 포함되어 그가 한 처분에 대해서는 피고가 된다. 행정소송법 제2조 제2항.","c":"상"},"세무사2022_59-78-2":{"f":"피고경정의 허가가 있는 때에는 종전의 피고에 대한 소송은 취하된 것으로 본다.","w":"피고경정이 허가되면 새 피고에 대한 소는 처음 소를 제기한 때에 제기된 것으로 보고, 종전 피고에 대한 소송은 취하된 것으로 본다. 행정소송법 제14조 제4항.","c":"상"},"세무사2023_60-44-5":{"f":"소송당사자에게 관할위반을 이유로 하는 이송신청권을 인정하고 있지 않다.","w":"관할위반으로 인한 이송은 법원의 직권 사항이고, 당사자의 이송신청은 직권 발동을 촉구하는 의미에 그친다. 당사자에게 이송신청권이 인정되는 것은 아니라는 것이 판례이다.","c":"중"},"세무사2023_60-45-1":{"f":"취소소송에 부당이득반환청구소송이 병합된 경우 부당이득반환청구가 인용되기 위해 취소판결이 확정될 필요는 없다.","w":"병합된 부당이득반환청구는 취소 판결의 확정 여부와 관계없이 인용될 수 있다. 처분의 위법 여부는 청구 판단의 선결문제로 같은 절차에서 판단한다.","c":"상"},"세무사2023_60-49-3":{"f":"행정소송 사건에서 「민사소송법」상 보조참가의 요건을 갖춘 경우에는 「민사소송법」상 보조참가가 허용된다.","w":"행정소송에서도 소송의 결과에 법률상 이해관계가 있는 자는 민사소송법에 따른 보조참가를 할 수 있다는 것이 판례이다.","c":"상"},"세무사2023_60-62-2":{"f":"甲이 제기하는 국가배상소송은 민사소송이므로 취소소송과의 사이에 소의 이송문제가 발생한다.","w":"국가배상소송은 민사소송으로 민사법원이 다루고 취소소송은 행정법원이 다루므로, 관련청구소송으로서 이송ㆍ병합이 문제 된다. 행정소송법 제10조.","c":"중"},"세무사2023_60-62-3":{"f":"사실심 변론종결 후에는 손해배상소송이 사후병합될 수 없다.","w":"관련청구소송의 병합은 사실심 변론종결 시까지만 가능하다. 취소소송의 확정판결이 나오지 않았다는 사정은 변론종결 후 병합을 허용하지 않는다.","c":"상"},"세무사2023_60-64-1":{"f":"두 소송이 관련청구이더라도 A 행정법원에 자동이송되지 않고, 당사자의 신청이나 법원의 직권에 의한 이송결정이 있어야 한다.","w":"관련청구소송의 이송은 법원이 상당하다고 인정하여 당사자의 신청 또는 직권으로 결정할 때 이루어지며, 자동 이송되지 않는다. 행정소송법 제10조 제1항.","c":"상"},"세무사2023_60-64-3":{"f":"甲의 이송신청에 대하여 B 지방법원이 각하결정을 하였다면 즉시항고 할 수 있다.","w":"관련청구소송의 이송 신청에 관한 결정에 대해서는 이송결정과 마찬가지로 민사소송법에 따라 즉시항고가 가능하다는 것이 출제 취지로 보인다. 근거 판례는 확인하지 못했다.","c":"하"},"세무사2024_61-62-1":{"f":"국회의 기관도 처분을 하는 경우에는 피고적격이 인정될 수 있다.","w":"국회사무총장, 국회도서관장 등 국회의 기관이 행정작용으로 처분을 하면 그 기관이 행정청으로서 피고가 될 수 있다.","c":"중"},"세무사2024_61-63-3":{"f":"관련청구의 병합이 있더라도 법원의 피고경정결정과는 무관하다.","w":"관련청구소송의 병합과 피고경정은 별개 제도이다. 관련청구를 병합하는 데 피고경정 결정이 필요한 것은 아니다.","c":"중"},"세무사2024_61-64-4":{"f":"소송에 참가한 제3자는 공동소송적 보조참가인으로서 소송수행을 한다.","w":"제3자 소송참가인에게는 필수적 공동소송에 관한 민사소송법 규정이 준용되어 공동소송적 보조참가인의 지위를 가진다. 행정소송법 제16조 제4항.","c":"상"},"세무사2024_61-65-5":{"f":"관련청구소송을 취소소송이 계속된 법원으로 이송할 수 있다.","w":"관련청구소송이 계속된 법원은 이를 취소소송이 계속된 법원으로 이송할 수 있다. 취소소송을 관련청구소송 법원으로 이송하는 것이 아니다. 행정소송법 제10조 제1항.","c":"상"},"세무사2025_62-43-5":{"f":"취소소송의 제1심관할법원은 피고의 소재지를 관할하는 행정법원으로 한다.","w":"취소소송의 제1심 관할법원은 피고 소재지를 관할하는 행정법원이다. 원고 소재지는 관할의 기준이 아니다. 행정소송법 제9조 제1항.","c":"상"},"세무사2025_62-44-1":{"f":"취소소송과 당해 처분과 관련되는 부당이득반환 청구소송이 다른 법원에 계속되고 있는 경우 법원은 부당이득반환 청구소송을 취소소송이 계속된 법원으로 이송할 수 있다.","w":"이송 방향은 관련청구소송에서 취소소송으로이다. 관련청구소송이 계속된 법원이 상당하다고 인정할 때 취소소송이 계속된 법원으로 이송한다. 행정소송법 제10조 제1항.","c":"상"},"세무사2025_62-48-1":{"f":"원고만 피고경정을 신청할 수 있다.","w":"피고경정은 원고가 피고를 잘못 지정한 경우에 원고의 신청에 의해 법원이 결정으로 허가한다. 제3자가 신청할 수 없다. 행정소송법 제14조 제1항.","c":"상"},"세무사2025_62-49-3":{"f":"「행정소송법」상의 소송참가 외에 「민사소송법」에 따른 보조참가도 허용된다.","w":"행정소송에서도 소송 결과에 법률상 이해관계가 있는 자는 민사소송법상 보조참가를 할 수 있다는 것이 판례이다.","c":"상"},"세무사2025_62-56-2":{"f":"취소소송을 제기하였다가 당사자소송으로 소 변경을 허용할 경우 제소기간 준수여부 판단기준은 당초 취소소송을 제기한 때이다.","w":"소의 종류를 변경하면 처음 소를 제기한 때 새로운 소가 제기된 것으로 보므로, 당초의 취소소송이 제소기간 안에 제기되었다면 준수한 것으로 본다.","c":"상"},"세무사2025_62-56-3":{"f":"「행정소송법」은 행정소송과 민사소송 간 소 변경을 규정하고 있지 않다.","w":"행정소송법은 항고소송과 당사자소송 사이의 소의 종류 변경만 규정한다. 행정소송과 민사소송 사이의 소 변경은 규정이 없다.","c":"중"},"세무사2025_62-56-4":{"f":"소 변경은 원고의 신청이 있어야 법원이 허가할 수 있다.","w":"소의 변경은 원고의 신청에 따라 법원이 결정으로 허가한다. 법원이 직권으로 할 수 없다. 행정소송법 제21조 제1항.","c":"상"},"세무사2025_62-56-5":{"f":"처분변경으로 인한 소 변경의 신청은 처분의 변경이 있음을 안 날로부터 60일 이내에 하여야 한다.","w":"처분변경으로 인한 소의 변경 신청기간은 변경이 있음을 안 날부터 60일이다. 90일이 아니다. 행정소송법 제22조 제2항.","c":"상"},"세무사2026_63-45-5":{"f":"본래의 취소소송이 부적법하여 각하되면 그에 병합된 관련청구도 각하된다.","w":"관련청구는 본래의 취소소송이 적법함을 전제로 병합되므로, 본체인 소가 부적법하면 병합된 관련청구소송도 함께 각하된다.","c":"상"},"세무사2026_63-48-1":{"f":"조례가 항고소송의 대상이 되는 경우 피고는 그 조례를 공포한 지방자치단체장이다.","w":"조례를 공포하는 권한은 지방자치단체장에게 있어 처분청은 지방자치단체장이며, 의결기관인 지방의회는 피고가 아니다. 교육조례는 교육감이 피고이다.","c":"상"},"세무사2026_63-48-2":{"f":"처분등이 있은 뒤에 그 처분등에 관계되는 권한이 다른 행정청에 승계된 경우 승계 행정청이 피고가 된다.","w":"처분 후 권한이 다른 행정청에 승계되면 승계한 행정청이 피고이다. 행정소송법 제13조 제1항 단서.","c":"상"},"세무사2026_63-48-3":{"f":"처분청과 그 처분을 통지한 자가 다른 경우 처분청이 취소소송의 피고가 된다.","w":"피고는 처분을 한 행정청이고, 단순히 처분을 통지한 자는 피고가 아니다.","c":"상"},"세무사2026_63-48-4":{"f":"지방법무사회는 공권력 행사의 주체가 될 수 있어 취소소송의 피고가 될 수 있다.","w":"지방법무사회가 법령에 따라 행정권한을 가지고 처분을 하면 행정청으로서 취소소송의 피고가 될 수 있다는 것이 판례이다.","c":"상"},"세무사2026_63-49-1":{"f":"취소소송의 원고가 피고를 잘못 지정한 때에는 법원은 원고의 신청에 의하여 피고를 경정한다.","w":"원고가 피고를 잘못 지정한 경우 피고경정은 원고의 신청이 있어야 하고 법원이 직권으로 경정할 수는 없다. 다만 법원은 석명권을 행사하여 경정을 유도해야 한다. 행정소송법 제14조 제1항.","c":"중"},"세무사2026_63-50-2":{"f":"행정청의 소송참가는 법원의 직권으로 결정할 수 있다.","w":"법원은 당사자 또는 해당 행정청의 신청이나 직권으로 다른 행정청을 소송에 참가시킬 수 있다. 행정소송법 제17조 제1항.","c":"상"},"세무사2026_63-50-3":{"f":"소송에 참가한 제3자는 공동소송적 보조참가인으로서 소송수행을 한다.","w":"제3자 소송참가인은 필수적 공동소송에 관한 민사소송법 규정이 준용되어 공동소송적 보조참가인의 지위를 가진다. 행정소송법 제16조 제4항.","c":"상"},"세무사2026_63-50-4":{"f":"법원이 제3자의 소송참가에 관한 결정을 하고자 할 때에는 미리 당사자 및 제3자의 의견을 들어야 한다.","w":"제3자 소송참가 결정에는 미리 당사자와 제3자의 의견을 들어야 한다. 행정소송법 제16조 제2항.","c":"상"},"세무사2026_63-50-5":{"f":"사립학교 교원이 교원소청심사위원회의 기각결정에 불복하여 행정소송을 제기한 경우, 소청심사의 피청구인이었던 사립학교의 장은 피고보조참가인으로서 소송에 참여할 수 있다.","w":"소청심사 결과에 이해관계가 있는 피청구인(사립학교의 장)은 민사소송법상 보조참가 요건을 갖추면 소송에 보조참가할 수 있다는 것이 판례이다.","c":"중"},"세무사2016_53-59-1":{"f":"도시기본계획은 장기발전방향을 제시하는 종합계획으로서 처분이 아니다.","w":"도시기본계획은 도시의 장기 발전방향을 제시하는 종합계획으로, 일반 국민의 권리의무에 직접 영향을 미치지 않아 처분이 아니다.","c":"상"},"세무사2016_53-59-2":{"f":"폐기물관리법상 폐기물처리업의 허가를 위한 사업계획에 대한 부적정통보는 처분이다.","w":"폐기물처리업 허가를 위한 사업계획 부적정 통보는 허가 신청 자체를 막는 효과가 있어 신청인의 법적 지위에 영향을 미치는 처분이다.","c":"상"},"세무사2016_53-59-3":{"f":"행정행위의 부관 중 부담은 항고소송의 대상이 될 수 있다.","w":"부담은 주된 행정행위에 붙은 독립된 처분의 성질이 있어 부담만을 대상으로 항고소송을 제기할 수 있다.","c":"상"},"세무사2016_53-59-5":{"f":"국가인권위원회의 성희롱결정과 시정조치의 권고는 성희롱 행위자와 사용자에게 법률상의 의무를 부담시키므로 처분이다.","w":"국가인권위원회의 성희롱 결정과 시정조치 권고는 행위자와 사용자에게 불이익을 주는 법적 효과가 있어 처분에 해당한다는 것이 판례이다.","c":"중"},"세무사2016_53-61-2":{"f":"일반적으로 과세처분취소소송에서 과세요건사실에 관한 입증책임은 피고(과세관청)에게 있다.","w":"과세처분의 적법성은 처분을 한 과세관청이 증명해야 한다. 비과세ㆍ면제 사유처럼 납세의무자에게 유리한 사실은 이를 주장하는 납세의무자가 증명한다.","c":"상"},"세무사2017_54-43-2":{"f":"재결의 내용의 위법은 재결 자체의 고유한 위법에 해당한다.","w":"재결 자체의 고유한 위법에는 주체, 절차, 형식 위법뿐 아니라 내용상의 위법도 포함된다.","c":"상"},"세무사2017_54-43-3":{"f":"재결 자체에 고유한 위법이 없음에도 제기된 재결취소소송은 기각판결의 대상이다.","w":"재결에 고유한 위법이 있는지는 본안에서 판단할 사항이어서, 고유한 위법이 없으면 소를 각하하지 않고 기각한다.","c":"중"},"세무사2017_54-43-4":{"f":"행정심판청구가 부적법하지 않음에도 불구하고 각하한 재결의 경우, 재결 자체의 고유한 위법이 인정된다.","w":"적법한 심판청구를 각하한 재결은 원처분에 없는 재결 고유의 하자가 있는 경우이다. 이때는 재결취소소송을 제기할 수 있다.","c":"상"},"세무사2017_54-43-5":{"f":"행정심판의 대상이 아닌 관념의 통지에 대하여 행한 인용재결의 경우, 재결 자체의 고유한 위법이 인정된다.","w":"행정심판의 대상이 아닌 행위에 대해 인용재결을 한 것은 심판대상이 아닌 사항에 대해 재결을 한 고유의 위법이 있다.","c":"중"},"세무사2021_58-66-1":{"f":"사립학교 교원에 대한 학교법인의 징계처분은 취소소송의 대상이 아니다.","w":"학교법인의 징계는 사법상 행위여서 취소소송의 대상이 아니다. 교원소청심사위원회의 결정이 취소소송의 대상이 된다.","c":"상"},"세무사2022_59-49-1":{"f":"조례는 집행행위의 개입 없이도 그 자체로서 직접 국민의 구체적인 권리의무에 영향을 미치는 법률상 효과를 발생하는 경우에는 항고소송의 대상이 된다.","w":"조례가 별도의 집행행위 없이 직접 국민의 권리의무를 규율하면 처분성이 인정되어 항고소송의 대상이 된다. 두밀분교를 폐지한 조례가 그 예이다.","c":"상"},"세무사2022_59-51-5":{"f":"행정청이 영업자에게 제재처분을 한 후 그 처분을 영업자에게 유리하게 변경하는 처분을 하였다면, 변경처분으로 유리하게 변경된 제재가 위법하다 하여 그 취소를 구하는 경우 취소소송의 대상은 변경처분이 아니라 변경된 내용의 당초 처분이다.","w":"감경하는 변경처분은 당초 처분의 일부 취소에 해당하므로 소송 대상은 감경된 내용으로 남아 있는 당초 처분이다.","c":"상"},"세무사2022_59-54-5":{"f":"기간제로 임용되어 임용기간이 만료된 조교수에 대하여 재임용을 거부하는 취지로 한 임용기간만료의 통지는 항고소송의 대상이 되는 행정처분에 해당한다.","w":"재임용 거부 취지의 임용기간 만료 통지는 교원의 법적 지위에 영향을 주므로 처분으로 보아 항고소송의 대상이 된다는 것이 전원합의체 판결이다.","c":"중"},"세무사2023_60-52-5":{"f":"공사중지명령의 상대방은 명령 이후에 그 원인사유가 소멸하였음을 들어 그 명령의 철회를 요구할 수 있는 조리상의 신청권이 있다.","w":"공사중지명령의 원인사유가 소멸한 경우 상대방에게 철회ㆍ해제를 요구할 조리상 신청권이 인정되고, 이를 거부하면 처분이 된다.","c":"중"},"세무사2023_60-55-1":{"f":"B의 입국금지결정은 항고소송의 대상인 처분이 아니다.","w":"입국금지결정은 행정 내부의 결정이고 그 자체로 상대방에게 통지되어 법적 효과를 발생시키지 않으므로 처분이 아니라는 것이 판례이다.","c":"중"},"세무사2023_60-55-2":{"f":"재외동포에 대한 사증발급은 A의 재량행위이다.","w":"재외동포에 대한 사증발급은 법무부장관의 재량행위이다. 기속행위가 아니므로 재량을 행사하지 않으면 위법이 된다.","c":"중"},"세무사2023_60-55-3":{"f":"C의 사증발급 불허 통지는 상급행정기관의 지시를 따른 것이라도 재량권을 행사하지 않았다면 위법하다.","w":"사증발급은 재량행위이므로 처분청이 스스로 재량을 행사해야 한다. 상급기관의 지시에만 따른 것이라면 재량 불행사로 위법할 수 있다.","c":"하"},"세무사2023_60-55-4":{"f":"B의 입국금지결정에는 공정력과 불가쟁력이 없다.","w":"입국금지결정은 처분이 아니므로 공정력이나 불가쟁력이 인정되지 않는다.","c":"중"},"세무사2024_61-68-1":{"f":"취소소송이란 위법한 처분등을 취소 또는 변경하는 소송이며, 여기서 ‘변경’이란 소극적 의미의 변경, 즉 일부 취소를 의미한다.","w":"취소소송에서 변경은 처분의 일부를 취소하는 소극적 변경이다. 처분을 다른 내용으로 바꾸는 적극적 변경은 허용되지 않는다.","c":"상"},"세무사2024_61-70-1":{"f":"행정심판의 재결을 거친 경우에도 원칙적으로 원처분을 취소소송의 대상으로 하여야 한다.","w":"원처분주의에 따라 취소소송은 원처분을 대상으로 하고, 재결은 재결 자체에 고유한 위법이 있을 때만 대상이 된다. 행정소송법 제19조 단서.","c":"상"},"세무사2024_61-70-2":{"f":"재결의 고유한 위법에는 내용상의 위법도 포함된다.","w":"재결 고유의 위법에는 재결의 주체, 절차, 형식 위법뿐 아니라 내용상 위법도 포함된다.","c":"상"},"세무사2024_61-70-3":{"f":"변경재결이 있는 경우 변경된 원처분을 소송대상으로 원처분청을 피고로 취소소송을 제기하여야 한다.","w":"감경 등 변경재결이 있으면 변경된 내용의 원처분이 소송 대상이 되고 피고는 원처분청이다. 행정심판위원회는 재결 고유의 위법을 다툴 때만 피고가 된다.","c":"중"},"세무사2024_61-70-5":{"f":"재결취소소송을 제기하였으나 재결에 고유한 위법이 없는 경우에는 기각판결을 하여야 한다.","w":"재결에 고유한 위법이 있는지는 본안 판단 사항이므로 고유한 위법이 없으면 소를 각하하지 않고 청구를 기각한다.","c":"중"},"세무사2026_63-54-3":{"f":"신청권의 존부는 관계 법규의 해석에 의하여 국민에게 신청권이 인정되는지 여부를 살펴 추상적으로 결정되는 것이다.","w":"신청권의 존부는 구체적 사건에서 신청인이 누구인지를 따지지 않고 관계 법규의 해석상 국민에게 인정되는지로 추상적으로 정한다. 신청이 인용될 수 있는지는 본안에서 판단한다.","c":"상"},"세무사2026_63-55-4":{"f":"사립학교 교원징계에 대한 교원소청심사위원회의 결정은 행정심판의 재결에 해당하지 않는다.","w":"사립학교 교원 징계는 학교법인이 한 사법적 행위여서 소청심사위원회의 결정은 행정심판의 재결이 아니라 처분이다. 소청심사위원회가 피고가 된다.","c":"상"},"세무사2016_53-60-2":{"f":"행정심판청구가 부적법하지 않음에도 각하한 재결은 취소소송의 대상이 될 수 있다.","w":"적법한 심판청구를 각하한 재결은 원처분에 없는 재결 고유의 위법이 있어 재결취소소송의 대상이 된다.","c":"상"},"세무사2016_53-63-2":{"f":"적법한 행정심판청구가 있은 때의 제소기간은 재결서의 정본을 송달받은 날부터 기산한다.","w":"행정심판을 거친 경우 취소소송은 재결서 정본을 송달받은 날부터 90일 이내에 제기한다. 심판청구일이 아니다. 행정소송법 제20조 제1항 단서.","c":"상"},"세무사2016_53-63-3":{"f":"처분등이 있음을 안 날부터 90일이라는 제소기간은 불변기간이다.","w":"제소기간은 불변기간이므로 법원이 늘이거나 줄일 수 없고, 당사자가 책임질 수 없는 사유가 있으면 추후 보완이 가능하다. 행정소송법 제20조 제3항.","c":"상"},"세무사2016_53-63-4":{"f":"취소소송의 제소기간의 규정은 당사자소송에 적용되지 않는다.","w":"제소기간 규정(제20조)은 당사자소송에 준용되지 않는다. 당사자소송은 개별 법령에 제소기간이 있을 때만 그 기간이 적용되고 이는 불변기간이다. 행정소송법 제41조.","c":"상"},"세무사2016_53-63-5":{"f":"특정인에 대한 처분을 주소불명의 이유로 송달할 수 없어 관보에 공고한 경우 상대방이 그 처분이 있음을 현실적으로 안 날에 알았다고 보아야 한다.","w":"주소불명으로 송달이 불가능해 관보에 공고한 경우에는 공고 효력 발생일이 아니라 상대방이 처분이 있음을 현실적으로 안 날부터 제소기간이 진행된다.","c":"상"},"세무사2017_54-67-5":{"f":"부작위위법확인소송은 행정심판을 거친 경우에는 제소기간의 제한을 받는다.","w":"부작위 상태가 계속되는 동안은 제소기간 제한이 없지만, 행정심판을 거친 경우에는 재결서 정본을 송달받은 날부터 90일이라는 제소기간이 적용된다. 행정소송법 제38조 제2항, 제20조.","c":"상"},"세무사2017_54-80-1":{"f":"지방세부과처분에 대한 이의신청은 임의적 절차이고 심사청구 또는 심판청구가 필요적 전치절차이다.","w":"지방세 처분은 이의신청을 거치지 않아도 되고, 심사청구나 심판청구를 거쳐야 행정소송을 제기할 수 있다.","c":"중"},"세무사2017_54-80-3":{"f":"행정심판전치주의는 무효확인소송에는 적용되지 않는다.","w":"행정심판 전치에 관한 제18조는 무효등 확인소송에 준용되지 않는다. 무효확인소송은 행정심판을 거치지 않고 제기할 수 있다. 행정소송법 제38조 제1항.","c":"상"},"세무사2017_54-80-4":{"f":"행정심판전치주의의 예외가 되는 사유는 원고가 이를 소명하여야 한다.","w":"행정심판 없이 바로 제소할 수 있는 예외 사유가 있다는 점은 원고가 소명한다. 행정소송법 제18조 제3항.","c":"상"},"세무사2017_54-80-5":{"f":"부적법한 행정심판청구가 있었다면 재결청이 과오로 본안에 대하여 재결한 때에도 행정심판을 거친 것으로 볼 수 없다.","w":"심판청구가 부적법하면 재결청이 잘못하여 본안 재결을 했더라도 적법한 전심절차를 거친 것이 되지 않는다는 것이 판례이다.","c":"중"},"세무사2021_58-53-1":{"f":"행정심판에 의한 감액명령재결에 따른 감액처분이 있은 경우 취소소송의 제소기간은 재결서 정본을 송달받은 날로부터 90일 이내이다.","w":"감액처분은 당초 처분의 일부 취소로 이루어지므로 행정심판을 거친 경우의 기산점인 재결서 정본 송달일부터 90일을 적용한다.","c":"하"},"세무사2021_58-53-2":{"f":"소의 종류가 변경된 경우에는 새로운 소에 대한 제소기간의 준수는 처음 소를 제기한 때를 기준으로 하여야 한다.","w":"소의 종류를 변경하면 새로운 소는 처음 소를 제기한 때에 제기된 것으로 본다. 행정소송법 제21조 제4항, 제14조 제4항.","c":"상"},"세무사2021_58-53-4":{"f":"필요적 행정심판전치주의하에서 행정심판이 제기된 후 60일이 지나도 재결이 없는 경우 언제든지 취소소송을 제기할 수 있다.","w":"심판청구 후 60일이 지나도 재결이 없으면 재결 없이 취소소송을 제기할 수 있다. 30일이 아니라 60일이다. 행정소송법 제18조 제2항 제1호.","c":"상"},"세무사2021_58-53-5":{"f":"무효선언을 구하는 취소소송의 경우에도 제소기간의 제한이 있다.","w":"무효를 선언하는 의미의 취소소송도 취소소송의 형식이므로 제소기간과 행정심판 전치 요건을 갖추어야 한다.","c":"상"},"세무사2022_59-53-4":{"f":"고시에 의하여 불특정다수인을 대상으로 행정처분을 하는 경우, 그 행정처분에 이해관계를 갖는 자는 고시가 있었다는 사실을 현실적으로 알았는지와 관계없이 고시가 효력을 발생하는 날에 행정처분이 있음을 알았다고 보아야 한다.","w":"고시로 불특정다수에게 하는 처분은 고시의 효력이 발생한 날 모든 이해관계인이 처분이 있음을 안 것으로 본다.","c":"상"},"세무사2022_59-58-2":{"f":"「국가공무원법」에 따른 징계처분에 대하여는 소청심사위원회의 심사 결정을 거치지 않으면 취소소송을 제기할 수 없다.","w":"국가공무원의 징계 등 불이익처분은 소청심사위원회의 심사ㆍ결정을 거쳐야 하는 필요적 행정심판전치 대상이다.","c":"상"},"세무사2022_59-58-3":{"f":"필요적 행정심판전치주의가 적용되는 경우, 동종사건에 관하여 이미 기각재결이 있은 때에는 행정심판을 제기하지 않고 바로 취소소송을 제기할 수 있다.","w":"동종사건에 대해 이미 기각재결이 있으면 행정심판을 거치지 않고 소를 제기할 수 있는 예외에 해당한다. 행정소송법 제18조 제3항 제1호.","c":"상"},"세무사2022_59-58-4":{"f":"취소소송은 소장을 제출하여 제기하여야 하며 구술로 제기할 수 없다.","w":"소의 제기는 법원에 소장을 제출하는 서면 방식으로 한다. 구술로 제기할 수 없다.","c":"상"},"세무사2022_59-58-5":{"f":"행정심판을 거친 후 취소소송을 제기하는 경우에는 재결서 정본을 송달받은 날이 제소 기간의 기산점이 된다.","w":"행정심판을 거친 취소소송의 제소기간은 재결서 정본을 송달받은 날부터 90일이다. 발송한 날이 아니다. 행정소송법 제20조 제1항 단서.","c":"상"},"세무사2023_60-42-5":{"f":"동종사건에 관하여 이미 행정심판의 기각재결이 있은 때에는 행정심판을 거치지 않아도 된다.","w":"필요적 전치주의가 적용되는 경우에도 동종사건에 대한 기각재결이 이미 있었다면 행정심판을 거칠 필요가 없다. 행정소송법 제18조 제3항 제1호.","c":"상"},"세무사2023_60-78-1":{"f":"특정인에 대한 행정처분을 주소불명 등의 이유로 송달할 수 없어 관보에 공고한 경우에는, 상대방이 그 행정처분이 있음을 현실적으로 안 날에 알았다고 보아야 한다.","w":"공고 효력발생일을 제소기간의 기산일로 삼는 것은 고시로 불특정다수에게 하는 처분의 경우이다. 특정인에 대한 처분을 공고한 경우에는 상대방이 현실적으로 안 날부터 기산한다.","c":"상"},"세무사2023_60-80-1":{"f":"甲은 행정심판을 거치지 아니하고도 이 사건 처분에 대한 취소소송을 제기할 수 있다.","w":"행정심판 전치는 원칙적으로 임의적이다. 필요적 전치가 적용되는 특별한 법률 규정이 없다면 행정심판을 거치지 않고도 취소소송을 제기할 수 있다. 행정소송법 제18조 제1항.","c":"중"},"세무사2023_60-80-3":{"f":"甲이 제기한 행정심판에서 이 사건 처분이 1개월로 감경된 후 취소소송을 제기할 경우 소송의 대상은 감경되고 남은 1개월에 해당하는 처분이다.","w":"일부 취소 재결이나 감경은 원처분 중 남은 부분을 대상으로 한다. 감경된 1개월의 처분이 소송 대상이다.","c":"중"},"세무사2023_60-80-4":{"f":"A시의 장이 이 사건 처분에 대한 취소소송의 피고이다.","w":"취소소송의 피고는 처분을 한 행정청이다. 지방자치단체 자체가 아니라 그 장이 피고가 된다.","c":"중"},"세무사2023_60-80-5":{"f":"행정소송법상 이 사건 처분과 같은 청소년에 관한 사건에 대해서도 집행정지가 인정된다.","w":"행정소송법의 집행정지는 처분의 종류와 관계없이 요건을 갖추면 인정되며, 청소년 관련 사건이라는 이유로 배제하는 규정은 없다.","c":"하"},"세무사2024_61-54-1":{"f":"처분에 대한 무효확인의 소에 그 처분의 취소를 구하는 소를 추가적으로 병합하는 경우, 주된 청구인 무효확인의 소가 제소기간 내에 제기되었다면 추가로 병합된 취소청구의 소도 적법하게 제기된 것으로 본다.","w":"추가 병합된 취소청구도 제소기간의 제한을 받지만, 주된 청구가 기간 안에 제기되었다면 취소청구도 기간 안에 제기된 것으로 본다는 것이 판례이다.","c":"중"},"세무사2024_61-54-2":{"f":"부작위상태가 계속되더라도 행정심판을 거쳐 부작위위법확인소송을 제기하는 경우에는 제소기간의 제한을 받는다.","w":"행정심판을 거친 부작위위법확인소송은 재결서 정본을 송달받은 날부터 90일의 제소기간이 적용된다. 행정소송법 제38조 제2항, 제20조.","c":"상"},"세무사2024_61-54-4":{"f":"행정청이 처분을 하면서 법정 제소기간보다 긴 기간으로 제소기간을 고지하였더라도 법정 제소기간이 지나 제기한 소는 부적법하다.","w":"행정소송법에는 제소기간의 불고지ㆍ오고지의 효과에 관한 규정이 없으므로 고지된 긴 기간이 법정 제소기간을 대신하지 않는다.","c":"중"},"세무사2024_61-54-5":{"f":"당사자소송에 관하여 법령에 제소기간을 정한 경우, 그 기간은 불변기간이므로 법원은 제소기간을 연장할 수 없다.","w":"당사자소송의 법령상 제소기간은 불변기간이다. 행정소송법 제41조.","c":"상"},"세무사2024_61-77-1":{"f":"","w":"단독으로는 틀린 진술이 아니다. 지방세 처분에 대해서도 감사원 심사청구를 거칠 수 있고 그 결정에는 곧바로 행정소송을 제기할 수 있다. 이 문제의 정답 선지는 지방세에 대한 시ㆍ도지사 심사청구 항목이다.","c":"하"},"세무사2024_61-77-2":{"f":"","w":"단독으로는 틀린 진술이 아니다. 국세는 국세청장에게 하는 심사청구를 거쳐 행정소송을 제기할 수 있다. 이 문제의 정답 선지는 지방세에 대한 시ㆍ도지사 심사청구 항목이다.","c":"하"},"세무사2024_61-77-3":{"f":"","w":"단독으로는 틀린 진술이 아니다. 국세는 조세심판원장에게 하는 심판청구를 거쳐 행정소송을 제기할 수 있다. 이 문제의 정답 선지는 지방세에 대한 시ㆍ도지사 심사청구 항목이다.","c":"하"},"세무사2024_61-77-5":{"f":"","w":"단독으로는 틀린 진술이 아니다. 지방세도 조세심판원장에게 하는 심판청구를 거쳐 행정소송을 제기할 수 있다. 이 문제의 정답 선지는 지방세에 대한 시ㆍ도지사 심사청구 항목이다.","c":"하"},"세무사2025_62-51-2":{"f":"전심절차에 있어서의 주장과 행정소송에 있어서의 주장은 반드시 일치할 필요가 없으므로 전심절차에 있어서 주장하지 아니한 사항도 행정소송에서 주장할 수 있다.","w":"전심에서 주장한 내용과 소송에서의 주장이 전혀 별개의 것이 아닌 한 반드시 일치할 필요는 없고, 전심에서 주장하지 않은 사항도 소송에서 주장할 수 있다.","c":"상"},"세무사2025_62-55-2":{"f":"부작위위법확인소송의 경우 행정심판을 거쳤다면 제소기간의 제한을 받는다.","w":"행정심판을 거친 부작위위법확인소송은 재결서 정본을 송달받은 날부터 90일의 제소기간이 있다. 거치지 않은 경우에 한해 부작위 상태가 계속되는 동안 제한이 없다.","c":"상"},"세무사2025_62-55-3":{"f":"필요적 행정심판전치주의 하에서 행정심판 제기 후 60일이 지나도 재결이 없는 경우 언제든지 취소소송을 제기할 수 있다.","w":"심판 제기 후 60일이 지나도 재결이 없으면 재결 없이 취소소송을 제기할 수 있다. 30일이 아니다. 행정소송법 제18조 제2항 제1호.","c":"상"},"세무사2025_62-55-4":{"f":"「행정소송법」에는 제소기간 불고지 및 오고지의 효과에 관하여 규정하고 있지 않다.","w":"행정소송법에는 소 제기에 필요한 사항의 고지의무나 불고지ㆍ오고지의 효과에 대한 규정이 없다. 행정심판법에는 이를 정한 규정이 있다.","c":"상"},"세무사2025_62-55-5":{"f":"행정심판 청구기간을 도과하여 각하된 후 재결서 송달일부터 90일 내에 취소소송을 제기하였더라도 제소기간을 준수한 것으로 볼 수 없다.","w":"부적법한 심판청구를 각하한 재결 뒤에는 재결서 송달일이 아니라 원처분이 있음을 안 날을 기준으로 제소기간을 계산한다는 것이 판례이다.","c":"중"},"세무사2026_63-52-3":{"f":"재결청의 재조사결정에 따른 행정소송의 제소기간의 기산점은 재조사결정에 따른 후속 처분의 통지를 받은 날이다.","w":"재조사결정은 후속 처분이 있어야 완성되는 중간적 결정이므로, 제소기간은 이의신청 대상인 처분의 통지일이 아니라 후속 처분의 통지를 받은 날부터 기산한다.","c":"상"},"세무사2026_63-53-5":{"f":"필요적 행정심판전치가 적용되는 경우, 행정심판전치의 요건은 사실심 변론종결 시까지 충족하면 된다.","w":"전치 요건은 제소 당시에 흠결되어 있어도 사실심 변론종결 시까지 갖추면 하자가 치유된다는 것이 판례이다.","c":"상"},"세무사2016_53-73-1":{"f":"집행정지결정사건은 본안이 계속된 법원의 관할이다.","w":"집행정지는 본안이 계속된 법원이 결정한다. 본안이 상급심에 있으면 그 상급심 법원이 관할이므로 제1심 법원으로 고정되지 않는다. 행정소송법 제23조 제2항.","c":"중"},"세무사2016_53-73-2":{"f":"집행정지의 결정에 대한 즉시항고에는 결정의 집행을 정지하는 효력이 없다.","w":"집행정지결정에 대해 즉시항고를 할 수 있으나 즉시항고에는 결정의 집행정지 효력이 없다. 행정소송법 제23조 제5항.","c":"상"},"세무사2016_53-73-3":{"f":"본안청구가 이유 없음이 명백한 경우에는 법정요건이 충족되어도 집행정지는 인정되지 않는다.","w":"신청인의 본안청구가 이유 없음이 명백하면 집행정지를 할 수 없다. 이는 집행정지의 소극적 요건으로 판례가 인정한다.","c":"상"},"세무사2016_53-73-4":{"f":"회복하기 어려운 손해의 주장ㆍ소명책임은 신청인에게 있다.","w":"회복하기 어려운 손해가 있다는 점은 집행정지를 신청한 사람이 주장하고 소명한다. 공공복리에 중대한 영향을 미칠 우려는 행정청이 소명한다.","c":"상"},"세무사2017_54-58-3":{"f":"집행정지결정이 있은 후 본안소송이 취하된 경우, 집행정지결정의 효력은 당연히 소멸한다.","w":"집행정지는 본안소송이 계속 중임을 전제로 하므로 본안소송이 취하되면 별도의 취소결정 없이 집행정지결정의 효력이 소멸한다.","c":"중"},"세무사2022_59-60-3":{"f":"처분등이나 그 집행 또는 절차의 속행으로 인하여 생길 회복하기 어려운 손해를 예방하기 위하여 긴급한 필요가 있을 때에 인정된다.","w":"집행정지의 요건은 ‘중대한 손해’가 아니라 ‘회복하기 어려운 손해’이다. 중대한 손해는 행정심판법상 집행정지 요건이다. 행정소송법 제23조 제2항.","c":"상"},"세무사2023_60-56-1":{"f":"집행정지결정의 효력은 집행정지기간이 만료되면 장래를 향하여 효력을 상실한다.","w":"집행정지결정은 장래를 향해서만 효력이 있고, 기간이 만료되어도 소급해서 효력을 잃지 않는다.","c":"상"},"세무사2023_60-56-2":{"f":"집행정지결정은 관계행정기관에도 미친다.","w":"집행정지결정에는 기속력 규정(제30조 제1항)이 준용되어 당사자인 행정청과 관계행정청을 기속한다. 행정소송법 제23조 제6항.","c":"상"},"세무사2023_60-56-3":{"f":"집행정지신청에 대한 기각의 결정에 대하여도 즉시항고 할 수 있다.","w":"집행정지의 신청에 대한 결정에는 인용이든 기각이든 즉시항고할 수 있다. 다만 즉시항고에는 결정의 집행을 정지하는 효력이 없다. 행정소송법 제23조 제5항.","c":"상"},"세무사2023_60-56-5":{"f":"집행정지결정을 한 후 본안소송이 취하되면 집행정지결정의 효력은 소멸한다.","w":"집행정지는 본안소송이 계속 중임을 전제로 하므로 본안소송이 취하되면 결정 주문에서 정한 기간이 남아 있어도 효력이 소멸한다.","c":"중"},"세무사2023_60-60-3":{"f":"집행정지신청이 신청요건을 결여하여 부적법하면 법원은 그 신청을 각하하여야 한다.","w":"신청요건을 갖추지 못한 부적법한 신청은 각하한다. 기각은 요건을 갖췄으나 이유가 없는 신청에 하는 결정이다.","c":"상"},"세무사2024_61-76-5":{"f":"집행정지결정의 효력이 소멸하는 경우 특별한 사정이 없는 한 집행정지기간 동안 교부된 보조금의 반환을 명할 수 있다.","w":"집행정지는 처분의 효력을 장래를 향해 일시 정지할 뿐이어서, 본안에서 처분이 유지되어 집행정지가 소멸하면 처분의 효력이 되살아나 정지기간 중 교부된 보조금의 반환을 명할 수 있다.","c":"하"},"세무사2025_62-53-1":{"f":"집행정지의 소극적 요건인 ‘공공복리에 중대한 영향을 미칠 우려’에 대한 주장ㆍ소명 책임은 행정청에게 있다.","w":"공공복리에 중대한 영향을 미칠 우려가 있다는 점은 소극적 요건으로 이를 주장하는 행정청이 소명한다.","c":"상"},"세무사2025_62-53-2":{"f":"집행정지는 본안소송이 계속될 것을 요하고, 그 본안소송이 소송요건을 갖춘 적법한 것이어야 한다.","w":"본안소송이 부적법하여 각하될 것이 명백한 경우에는 집행정지의 이익이 없어 신청이 받아들여지지 않는다. 본안이 소송요건을 갖추어야 한다.","c":"중"},"세무사2025_62-53-4":{"f":"집행정지는 법원의 직권으로도 할 수 있다.","w":"집행정지는 당사자의 신청 또는 법원의 직권으로 결정한다. 행정소송법 제23조 제2항.","c":"상"},"세무사2025_62-53-5":{"f":"신청인의 본안청구가 이유 없음이 명백하지 않아야 한다는 것은 집행정지의 요건에 포함된다.","w":"본안청구가 이유 없음이 명백하지 않아야 한다는 것은 판례가 인정하는 집행정지의 소극적 요건이다.","c":"상"},"세무사2025_62-54-4":{"f":"본안에서 계쟁처분이 최종적으로 적법한 것으로 확정되더라도 집행정지결정의 효력은 소급하여 소멸하지 않는다.","w":"집행정지는 장래에 대해서만 효력이 있어 본안 판결의 확정으로 소급하여 없어지지 않는다. 본안 판결 선고로 결정의 효력이 장래를 향해 소멸한다.","c":"중"},"세무사2026_63-57-5":{"f":"「민사집행법」상의 가처분으로 행정청의 행정행위 금지를 구하는 것은 허용되지 않는다.","w":"행정청의 처분을 대상으로 한 민사상 가처분은 허용되지 않는다는 것이 판례다. 행정처분의 효력 정지는 행정소송법상 집행정지로 한다.","c":"상"},"세무사2016_53-41":{"w":"지방의회 의원에 대한 징계처분은 행정처분으로서 항고소송의 대상이 된다.\n단순한 사실관계 존부, 반사적 이익의 침해, 국회의원에 대한 징계처분(사법심사 대상이 아님), 공정거래위원회의 고발조치(내부적 행위)는 행정소송으로 다툴 수 없다.","c":"중"},"세무사2016_53-44":{"w":"ㄴ O: 공법상 신분·지위 확인소송은 당사자소송이다.\nㄹ O: 신청에 따른 처분의 절차 위법도 취소사유다.\nㅁ O: 공법상 계약에 관한 소송은 당사자소송이다.\nㄱ X: 과태료 부과는 질서위반행위규제법의 이의제기와 비송절차로 다투며 행정소송이 아니다.\nㄷ X: 거부처분에 대한 가처분은 허용되지 않는다.\nㅂ X: 예방적 금지소송은 허용되지 않는다.","c":"중"},"세무사2016_53-53":{"w":"처분의 효력 유무가 민사소송의 선결문제인 경우 행정소송법 제11조 1항이 준용하는 규정은 행정청의 소송참가(제17조), 행정심판기록 제출명령(제25조), 직권심리(제26조), 소송비용 재판의 효력(제33조)이다.\n재판관할과 사정판결은 준용되지 않는다.","c":"상"},"세무사2016_53-79":{"w":"행정소송에 대한 대법원판결로 명령·규칙이 헌법 또는 법률에 위반된다고 확정되면 대법원은 지체 없이 그 사유를 행정안전부장관에게 통보한다(행정소송법 제6조 1항). 문항 당시의 명칭은 행정자치부장관이다.","c":"중"},"세무사2017_54-41":{"w":"당사자소송은 행정소송법에 원고적격을 법률에 정한 자로 한정하는 규정이 없다. 공법상 법률관계의 당사자가 제기한다.\n기관소송과 민중소송은 법률이 정한 경우에 법률에 정한 자만 제기할 수 있다(제45조).","c":"중"},"세무사2017_54-42":{"w":"집행행위 없이 그 자체로 국민의 권리를 직접 제한하는 조례는 처분성이 인정되어 무효확인소송을 제기할 수 있다.\n의무이행소송, 예방적 부작위소송, 검사에 대한 압수물 환부이행소송은 행정소송법상 허용되지 않는다.","c":"상"},"세무사2017_54-44":{"w":"행정소송법상 행정소송은 항고소송, 당사자소송, 민중소송, 기관소송 네 가지다(제3조). 민중소송이 해당한다.","c":"상"},"세무사2022_59-45":{"w":"행정소송법 제3조·제4조에 명시된 소송은 취소소송, 무효등 확인소송, 부작위위법확인소송(이상 항고소송), 당사자소송, 민중소송, 기관소송이다. 예방적 부작위청구소송은 명시되어 있지 않다.","c":"상"},"세무사2023_60-43":{"w":"행정소송법 제8조 2항: 이 법에 특별한 규정이 없는 사항은 법원조직법과 민사소송법 및 민사집행법을 준용한다.","c":"상"},"세무사2023_60-50":{"w":"행정소송의 종류는 항고소송, 당사자소송, 민중소송, 기관소송이다. 예방적 부작위청구소송은 이에 속하지 않는다.","c":"상"},"세무사2023_60-71":{"w":"ㄱ O: 무효확인소송은 제소기간 제한이 없어 처분 후 2년이 지나도 제기할 수 있다.\nㄴ X: 검사에 대한 압수물 환부이행소송은 허용되지 않는다.\nㄷ X: 예방적 부작위청구소송은 허용되지 않는다.\nㄹ X: 행정청의 작위의무 확인소송도 허용되지 않는다.","c":"중"},"세무사2024_61-57":{"w":"공법상 계약에 따른 의무의 이행을 청구하는 소송은 공법상 법률관계에 관한 당사자소송으로 허용된다.\n의무이행소송, 사실관계 부존재확인소송, 작위의무확인소송, 예방적 확인소송은 행정소송법상 허용되지 않는다.","c":"상"},"세무사2024_61-66":{"w":"행정소송에는 행정소송법이 우선하고 법원조직법·민사소송법·민사집행법(제8조 2항), 행정소송규칙이 적용된다. 행정심판법은 적용·준용되지 않는다.","c":"상"},"세무사2024_61-69":{"w":"행정소송법 제6조 1항: 행정소송에 대한 대법원판결에 의하여 명령·규칙이 헌법 또는 법률에 위반된다는 것이 확정된 경우에는 대법원은 지체 없이 그 사유를 행정안전부장관에게 통보하여야 한다.","c":"상"},"세무사2025_62-41":{"w":"행정소송법 제3조: 항고소송은 행정청의 처분등이나 부작위에 대하여 제기하는 소송이고, 기관소송은 국가 또는 공공단체의 기관 상호간의 권한 존부·행사에 관한 다툼에 대한 소송이다.","c":"상"},"세무사2025_62-75":{"w":"명예퇴직한 법관의 미지급 명예퇴직수당 청구는 공법상 금전지급청구로 당사자소송이다.\n장래 처분을 구하는 소송, 이행판결을 구하는 소송, 준공처분 금지 소송, 행정처분을 직접 행하는 형성판결을 구하는 소송은 행정소송법상 허용되지 않는다.","c":"상"},"세무사2026_63-47":{"w":"취소소송의 소송요건은 대상적격, 원고적격, 피고적격, 소의 이익, 제소기간, 필요한 경우 행정심판전치 등이다. 처분의 위법성은 본안에서 판단하는 사항이다.","c":"상"},"세무사2016_53-68":{"w":"거부처분취소판결 후 행정청이 재처분을 하지 않을 때 법원이 상당한 기간을 정하고 지연기간에 따른 배상을 명하는 제도는 간접강제다(행정소송법 제34조).","c":"상"},"세무사2016_53-71":{"w":"행정소송법 제32조: 취소청구가 사정판결에 의하여 기각되거나 행정청이 처분등을 취소 또는 변경함으로 인하여 청구가 각하 또는 기각된 경우 소송비용은 피고가 부담한다.","c":"상"},"세무사2016_53-77":{"w":"취소판결의 기속력은 인용판결에 인정되고, 집행정지결정에도 준용된다(제23조 6항, 제30조 1항). 각하·기각판결에는 기속력이 없다.","c":"상"},"세무사2017_54-50":{"w":"금액이 분리되는 기속행위의 금전부과처분(ㄱ 과세처분, ㄴ 개발부담금부과처분)은 법원이 적정액을 산정할 수 있어 초과 부분만 취소할 수 있다.\n재량이 있는 과징금부과처분(ㄷ)과 영업정지처분(ㄹ)은 법원이 적정한 범위를 정할 수 없어 전부 취소한다.","c":"중"},"세무사2017_54-52":{"w":"취소판결의 제3자효(제29조 1항)는 무효확인소송(제38조 1항)과 부작위위법확인소송(제38조 2항)에 준용되고, 집행정지결정도 제3자효가 있다(제23조 6항). 당사자소송에는 제3자효 규정이 준용되지 않는다.","c":"상"},"세무사2017_54-55":{"w":"주문은 사정판결이다.\n③ 사정판결을 할 때 법원은 원고가 입게 될 손해의 정도, 배상방법 등을 미리 조사해야 한다(제28조 2항). 조사할 필요가 없다는 ③이 옳지 않다.\n① 사정판결은 취소소송에만 인정된다. ② 공공복리 판단은 사실심 변론종결시를 기준으로 한다. ④ 당사자의 명백한 주장이 없어도 직권으로 할 수 있다. ⑤ 석명권 행사 취지가 맞다.","c":"중"},"세무사2017_54-74":{"w":"무효인 과세처분에 따른 환급 문제는 민사상 부당이득 반환청구로 해결해야 하고, 환급거부결정은 항고소송의 대상인 처분이 아니다. 소송요건을 갖추지 못해 각하판결을 한다.","c":"중"},"세무사2021_58-51":{"w":"행정소송법 제6조 1항: 대법원은 지체 없이 그 사유를 행정안전부장관에게 통보한다.","c":"상"},"세무사2022_59-76":{"w":"ㄱ O: 사정판결은 처분등을 취소하는 것이 현저히 공공복리에 적합하지 않을 때 청구를 기각하는 제도이고, 재결취소소송에도 적용된다(제28조 1항).\nㄴ O: 사정판결 규정은 무효등 확인소송과 부작위위법확인소송에 준용되지 않는다.\nㄷ X: 공공복리 판단 기준 시점은 처분시가 아니라 사실심 변론종결시다.\nㄹ X: 당사자의 명백한 주장이 없어도 법원은 직권으로 사정판결을 할 수 있다.","c":"중"},"세무사2022_59-77":{"w":"ㄱ O: 집행정지결정은 제3자에게도 효력이 있다(제23조 6항, 제29조 2항).\nㄹ O: 부작위위법확인판결에는 제29조가 준용되어 제3자효가 있다(제38조 2항).\nㄴ X: 환급세액 지급을 명하는 판결은 당사자소송 이행판결이다.\nㄷ X: 청구기각판결에는 제3자효가 없다.","c":"중"},"세무사2022_59-80":{"w":"간접강제는 거부처분취소판결(제34조)과 부작위위법확인판결(제38조 2항 준용)에 인정된다.\n부작위위법확인판결인 ③이 해당한다. 수용재결 취소, 부과처분 일부취소, 무효확인판결, 금전지급 명령 판결은 간접강제 대상이 아니다.","c":"중"},"세무사2023_60-61":{"w":"ㄱ O: 정당한 부과금액을 산정할 수 있는 기속행위 금전부과처분은 일부취소가 가능하다.\nㄹ O: 레이카크레인은 특수면허로만 운전할 수 있으므로 나머지 면허의 취소는 위법해 그 부분만 취소할 수 있다.\nㄴ X: 재량행위인 과징금부과처분은 법원이 적정액을 정할 수 없어 전부 취소한다.\nㄷ X: 적법한 부과금액을 산출할 수 없으면 전부 취소한다.","c":"중"},"세무사2023_60-66":{"w":"제3자의 재심청구(제31조)는 확정판결이 있음을 안 날부터 30일 이내, 판결이 확정된 날부터 1년 이내에 제기해야 하고, 이 기간은 불변기간이다.","c":"상"},"세무사2024_61-46":{"w":"ㄱ X, ㄴ X: 재량이 있는 영업정지·과징금 처분은 법원이 적정한 정도를 정할 수 없어 전부 취소한다.\nㄷ O: 세대별로 가분되는 분양전환승인은 일부 취소가 가능하다.\nㄹ O: 공개 가능한 부분이 분리되면 그 부분만 일부 취소한다.","c":"중"},"세무사2024_61-67":{"w":"ㄴ O: 일부취소판결은 인용판결이어서 기속력이 있다.\nㄷ O: 무효확인판결에도 기속력이 준용된다(제38조 1항).\nㅁ O: 당사자소송 이행판결에도 기속력이 준용된다(제44조 1항).\nㄱ X: 각하판결, ㄹ X: 사정판결(기각판결)에는 기속력이 없다.","c":"중"},"세무사2025_62-70":{"w":"제3자의 재심청구(제31조)는 확정판결을 안 날부터 30일 이내, 판결 확정일부터 1년 이내에 제기하며 이 기간은 불변기간이다.","c":"상"},"세무사2026_63-65":{"w":"사정판결에서는 원고가 입게 될 손해 등 권익 침해의 내용, 위법사유의 내용·발생원인과 전체 처분에서 그 부분이 차지하는 비중, 취소 시 예상되는 결과 등을 고려한다.\n②는 위법사유와 그 비중을 고려하는 것이다. 나머지 선지는 처분청의 손해, 처분청의 신뢰보호, 처분청의 피해 전보처럼 고려 주체를 처분청으로 바꾸거나 처분 상대방에게 해당하는 사정이다.","c":"하"},"세무사2026_63-67":{"w":"판결서에는 당사자와 법정대리인, 주문, 청구취지, 이유, 변론종결일, 법원을 적는다(민사소송법 제208조). 청구의 원인은 기재사항이 아니다.","c":"중"},"세무사2026_63-69":{"w":"행정소송법 제30조: 처분등을 취소하는 확정판결은 그 사건에 관하여 당사자인 행정청과 그 밖의 관계행정청을 기속하고, 거부처분을 취소하는 판결이 확정되면 그 처분을 행한 행정청은 판결의 취지에 따라 다시 이전의 신청에 대한 처분을 해야 한다.","c":"상"},"세무사2016_53-46":{"w":"압류처분 후에 압류된 부동산을 매수한 자는 압류의 부담을 안고 취득한 것이므로 압류처분의 취소를 구할 법률상 이익이 없어 원고적격이 인정되지 않는다.\n연대납세의무자, 환경영향평가대상지역 주민, 방사성물질 피해 예상지역 주민, 기존 담배소매인은 판례상 원고적격이 인정된다.","c":"중"},"세무사2016_53-51":{"w":"의료법에 의한 자격정지처분에서 가중처분 규정이 법률에 있는 경우, 정지기간이 지난 뒤에도 가중 불이익이 남아 있으므로 처분 취소를 구할 소의 이익이 인정된다.\n불합격 후 새 시험에 합격한 경우, 감면처분 후 선행 과징금처분, 건축공사 완료 후 허가, 대집행 완료 후 계고처분은 소의 이익이 없다.","c":"중"},"세무사2016_53-66":{"w":"생태·자연도 등급 변경은 일반적·추상적인 지정에 불과해 인근 주민에게 개별적·직접적·구체적 이익이 있다고 볼 수 없어 무효확인의 원고적격이 부정된다.","c":"중"},"세무사2017_54-63":{"w":"사업양도계약의 무효를 주장하는 양도인은 지위승계신고 수리처분으로 영업을 잃는 불이익을 받으므로 수리처분의 취소를 구할 소의 이익이 있다.\n인가의 기본행위 하자, 입주자의 사용검사처분, 이전 직위해제처분, 새 시험에 합격한 불합격처분은 소의 이익이 부정된다.","c":"중"},"세무사2017_54-68":{"w":"건축허가에 따른 공사가 완료된 뒤에는 이웃주민이 허가처분의 취소를 구할 소의 이익이 없다.\n의원 제명의결(임기만료 후에도 보수 청구), 불합격처분(입학시기 도과), 감봉처분(퇴직 후), 영치품 사용 불허처분은 소의 이익이 인정된다.","c":"중"},"세무사2021_58-60":{"w":"개발제한구역 해제대상에서 누락된 토지의 소유자는 해제 결정을 다툴 법률상 이익이 없어 원고적격이 인정되지 않는다.\n임차인, 기존 화물자동차운송사업자, 기존 약종상, 광업권설정허가로 이익을 침해당하는 토지 소유자는 원고적격이 인정된다.","c":"중"},"세무사2022_59-57":{"w":"약사에 대한 한약조제시험 합격처분의 무효확인을 구하는 한의사는 법률상 이익이 없어 원고적격이 부정된다.\n임차인대표회의, 환경영향평가 대상지역 주민, 기존 시내버스업자, 취수장 물을 공급받는 주민은 인정된다.","c":"중"},"세무사2024_61-80":{"w":"사업양도에 따라 지위승계신고가 수리된 경우, 사업양도가 무효라고 주장하는 양도인은 수리처분의 무효확인을 구할 소의 이익이 있다.\n재결 취소, 직권취소 후의 처분, 기간 만료 후의 계약해지, 조례 제정 후의 폐업결정은 소의 이익이 없다.","c":"중"},"세무사2025_62-47":{"w":"지방자치단체는 다른 지방자치단체의 장이 한 건축협의 취소를 다툴 원고적격이 있다(판례).\n대학 직원 노동조합, 기존 일반소매인, 대한의사협회, 한의사는 법률상 이익이 없어 원고적격이 부정된다.","c":"중"},"세무사2026_63-46":{"w":"다른 약사에 대한 약국개설등록처분으로 조제 기회를 잃은 기존 약국개설자는 법률상 이익이 인정되어 원고적격이 있다.\n경업자에게 불리한 처분을 다투는 기존 업자, 생태·자연도 변경에 대한 인근 주민, 수녀원, 노동조합은 원고적격이 부정된다.","c":"하"},"세무사2021_58-46":{"w":"부작위위법확인소송에는 집행정지(제23조)가 준용되지 않는다. 소송비용 재판의 효력, 직권심리, 기록 제출명령, 관련청구소송의 이송·병합은 준용된다(제38조 2항).","c":"상"},"세무사2022_59-42":{"w":"처분변경으로 인한 소의 변경(제22조)은 무효등 확인소송에는 준용되지만 부작위위법확인소송에는 준용되지 않는다. 재판관할, 제3자 소송참가, 공동소송, 행정청 소송참가는 둘 모두에 준용된다.","c":"중"},"세무사2024_61-51":{"w":"작위의무확인소송은 행정소송법상 허용되지 않는다.\n무효등 확인소송에는 유효·무효·실효·존재·부존재 확인소송이 포함된다(제4조 2호). 재결의 무효확인도 가능하다.","c":"상"},"세무사2026_63-74":{"w":"재판관할(제9조)과 재량처분의 취소(제27조)는 부작위위법확인소송에 준용된다(제38조 2항).\n처분변경으로 인한 소의 변경(제22조)과 집행정지(제23조)는 준용되지 않는다.","c":"중"},"세무사2016_53-62":{"w":"거부처분취소소송의 위법 판단 기준시는 처분시이고, 부작위위법확인소송은 부작위 상태가 계속되는 한 판결시(사실심 변론종결시)를 기준으로 한다.","c":"상"},"세무사2017_54-45":{"w":"재량남용 여부는 처분의 적법성에 관한 본안판단 사항이다.\n제소기간, 원고적격, 대상적격, 소의 이익은 본안 전의 소송요건이다.","c":"상"},"세무사2022_59-48":{"w":"선결문제 심리 시 준용되는 규정은 행정청의 소송참가(제17조), 기록 제출명령(제25조), 직권심리(제26조), 소송비용 재판의 효력(제33조)이다. 제3자의 소송참가(제16조)는 준용되지 않는다.","c":"상"},"세무사2023_60-65":{"w":"행정소송은 변론주의를 기본으로 하고 법원이 필요하면 직권으로 증거를 조사하는 직권심리를 보충적으로 허용한다(제26조). 직권탐지를 우선하는 것은 아니다.","c":"상"},"세무사2025_62-45":{"w":"선결문제 심리 시 준용되는 규정은 행정청 소송참가, 기록 제출명령, 직권심리, 소송비용 재판의 효력이다. 피고경정(제14조)은 준용되지 않는다.","c":"상"},"세무사2025_62-61":{"w":"원고적격, 소의 이익, 전심절차 준수, 처분성은 소송요건이다. 처분절차를 지켰는지는 처분의 위법 여부에 관한 본안 판단사항이다.","c":"상"},"세무사2025_62-62":{"w":"행정소송에서 법원이 당사자가 주장하지 않은 사실에 대해서도 직권으로 심리할 수 있는 직권심리주의(제26조)는 민사소송과 다른 특수한 심리 방법이다.","c":"상"},"세무사2025_62-63":{"w":"ㄴ O: 재량권의 일탈·남용은 이를 주장하는 원고가 증명한다.\nㄹ O: 허가기준 미달을 이유로 불허가한 처분이 적법하다는 점은 처분청이 주장·증명한다.\nㄱ X: 처분의 적법성은 일반적으로 피고 행정청이 증명한다.\nㄷ X: 소송상 증명은 자연과학적 증명이 아니라 고도의 개연성으로 족하다.","c":"중"},"세무사2026_63-44":{"w":"선결문제 심리에 준용되는 규정은 행정청의 소송참가(ㄴ)와 행정심판기록 제출명령(ㄹ)이다. 사정판결과 집행정지는 준용되지 않는다.","c":"상"},"세무사2026_63-61":{"w":"ㄱ O: 준농림지역 행위제한과 환경보전 등 중대한 공익상 필요는 같은 불허가 사유에 대한 기본적 사실관계가 동일하다.\nㄴ X: 계약 불이행과 공무원에게 뇌물을 준 사유는 사실관계가 다르다.\nㄷ X: 무자료주류판매·위장거래와 무면허판매업자에 대한 판매는 서로 다른 위반사실이다.","c":"하"},"세무사2016_53-58":{"w":"부가가치세 환급세액 지급청구는 법령에 따라 직접 발생하는 공법상 권리여서 당사자소송으로 한다.\n민주화운동 보상금 지급에 관한 소송은 심의위원회의 기각결정에 대한 불복이므로 취소소송이다.","c":"하"},"세무사2017_54-46":{"w":"민중소송은 국가 또는 공공단체의 기관이 법률에 위반되는 행위를 한 때 자기의 법률상 이익과 관계없이 그 시정을 구하는 소송이다(제3조 3호). 선거소송, 국민투표무효소송, 주민소송이 해당한다.\n지방의회 재의결에 대한 단체장·교육감의 소송은 기관소송이다.","c":"중"},"세무사2017_54-62":{"w":"ㄱ O: 지방자치단체의 보조금 반환 청구는 공법상 법률관계에 관한 당사자소송이다.\nㄴ O: 지방소방공무원의 초과근무수당 청구는 당사자소송이다.\nㄷ O: 명예퇴직수당 청구는 당사자소송이다.\nㄹ O: 인가·고시 전 조합 결의의 효력을 다투는 소송은 당사자소송이다.","c":"중"},"세무사2021_58-47":{"w":"당사자소송에는 취소소송의 공동소송(제15조)과 소송비용 부담(제32조)이 준용된다(제44조).\n간접강제(제34조)와 판결의 제3자효(제29조)는 당사자소송에 준용되지 않는다.","c":"중"},"세무사2021_58-48":{"w":"국가의 부가가치세 환급세액 지급의무는 법령에 따라 직접 발생하는 공법상 의무이므로 납세의무자의 지급청구는 당사자소송 절차에 따른다.","c":"상"},"세무사2021_58-49":{"w":"지방자치법상 주민소송은 주민이 자기의 법률상 이익과 관계없이 지방자치단체의 위법한 재무회계 행위의 시정을 구하는 민중소송이다.","c":"상"},"세무사2023_60-54":{"w":"서울시립무용단원 해촉, 공중보건의사 채용계약 해지, 부가가치세 환급세액 청구는 모두 공법상 법률관계에 관한 소송으로 당사자소송이다.","c":"중"},"세무사2023_60-70":{"w":"ㄱ O: 인가 전 조합 총회결의의 효력을 다투는 소송은 당사자소송이다.\nㄹ O: 명예퇴직수당 청구는 당사자소송이다.\nㄴ X: 조합과 조합장 사이의 선임·해임 법률관계는 사법상 관계로 민사소송이다.\nㄷ X: 관리처분계획의 취소를 구하는 소송은 항고소송이다.","c":"중"},"세무사2024_61-49":{"w":"민중소송은 법률이 정한 경우에 법률에 정한 자에 한하여 제기할 수 있다(제45조). ②가 옳지 않다.\n① 객관소송, ③④ 제46조 준용, ⑤ 지방자치법상 주민소송은 민중소송.","c":"상"},"세무사2024_61-56":{"w":"ㄱ O: 명예퇴직수당 청구는 당사자소송이다.\nㅁ O: 보조금 교부 부관상 반환의무에 따른 청구는 공법상 금전청구로 당사자소송이다.\nㄴ X: 조합임원 선임결의 무효확인은 사법상 민사소송이다.\nㄷ X: 인가·고시 후에는 관리처분계획 자체를 항고소송으로 다투고, 총회결의 무효확인은 소의 이익이 없다.\nㄹ X: 이주대책대상자 결정 전에는 수분양권 확인을 구할 법률상 지위가 없다.","c":"중"},"세무사2024_61-75":{"w":"기관소송은 법률이 정한 경우에 법률에 정한 자에 한하여 제기할 수 있다(제45조). 군수가 도지사의 취소처분을 다투는 소송은 지방자치법에 근거를 둔 소송이다.\n나머지는 국가기관·지방자치단체가 자기의 법적 지위를 다투는 항고소송이다.","c":"하"},"세무사2025_62-52":{"w":"당사자소송에는 재판관할(제9조), 직권심리(제26조), 행정심판기록 제출명령(제25조)이 준용된다(제44조 1항). 집행정지(제23조)는 준용되지 않는다.","c":"상"},"세무사2025_62-58":{"w":"산업단지관리공단의 입주계약 취소는 행정처분이므로 항고소송(취소소송)으로 다툰다. 당사자소송이라는 ①이 옳지 않다.","c":"중"},"세무사2025_62-76":{"w":"환매권의 존부 확인은 민사소송으로 다룬다는 것이 판례다. 당사자소송이 아니다.\n부가가치세 환급, 인가 전 조합 총회결의, 지방소방공무원 초과근무수당, 조세채권존재확인(국가가 제기)은 당사자소송이다.","c":"중"},"세무사2026_63-58":{"w":"도시정비법상 사업시행계획 인가 이전의 총회결의는 행정처분이 아니라 공법상 법률관계에 관한 것이어서 당사자소송으로 효력을 다툰다.","c":"중"},"세무사2026_63-72":{"w":"재개발조합을 상대로 한 조합원자격 확인과 지방소방공무원의 초과근무수당 청구는 모두 당사자소송이다.\n③ 법령에 제소기간이 정해져 있으면 그 기간은 불변기간이다(제41조).\n집행정지는 준용되지 않고, 직권심리와 기속력은 준용되며, 국가를 상대로 한 가집행선고 제한은 폐지되었다.","c":"중"},"세무사2026_63-79":{"w":"당사자소송은 국가·공공단체 그 밖의 권리주체를 피고로 한다(제39조). 항고소송은 처분등을 행한 행정청이 피고다(제13조).","c":"상"},"세무사2016_53-78":{"w":"ㄱ O: 소의 종류 변경은 청구의 기초에 변경이 없는 때에 허가한다(제21조 1항).\nㄷ O: 법원은 결정으로 소의 변경을 허가한다.\nㄴ X: 사실심 변론종결시까지 신청할 수 있다.\nㄹ X: 새로운 피고에 대한 소송은 처음 소를 제기한 때에 제기된 것으로 본다(제21조 4항, 제14조 4항).","c":"중"},"세무사2021_58-58":{"w":"ㄱ O: 행정소송법은 당사자능력 규정이 없고 민사소송법을 따른다.\nㄷ O: 국민권익위원회의 조치요구를 받은 소방청장은 이를 취소소송으로 다툴 당사자능력이 있다.\nㄴ X: 업무처리지침으로 사무를 시달받은 동장은 처분청이 되지 못하고 당사자능력이 없다.","c":"하"},"세무사2021_58-64":{"w":"간접강제 결정은 당사자의 신청이 있어야 하며 법원이 직권으로 할 수 없다(제34조 1항).\n피고경정(제14조 6항), 집행정지결정의 취소(제24조 2항 준용, 직권), 제3자의 소송참가(제16조), 행정청의 소송참가(제17조)는 직권으로 할 수 있다.","c":"상"},"세무사2023_60-46":{"w":"농지보전부담금 부과처분을 한 주체는 농림축산식품부장관이고, 한국농어촌공사는 수납 업무만 대행한다. 항고소송의 피고는 처분을 한 행정청인 농림축산식품부장관이다.","c":"중"},"세무사2023_60-51":{"w":"ㄴ O: 처분변경으로 인한 소의 변경은 처분의 변경이 있음을 안 날부터 60일 이내에 신청해야 한다(제22조 2항).\nㄹ O: 제22조는 취소소송과 무효등 확인소송, 당사자소송에 적용된다.\nㄱ X: 소의 변경 불허결정에는 독립하여 항고할 수 없다.\nㄷ X: 소의 변경 허가결정에 대하여 새로운 피고는 즉시항고할 수 있다(제21조 3항).","c":"하"},"세무사2024_61-71":{"w":"취소소송↔당사자소송 변경(ㄱ,ㄷ), 무효확인소송→취소소송(ㄴ), 이송결정 확정 후 민사소송→취소소송(ㄹ)은 모두 소 변경이 허가되면 새로운 소가 처음 소를 제기한 때 제기된 것으로 본다(제21조 4항, 제14조 4항).","c":"하"},"세무사2024_61-72":{"w":"수용재결 취소·무효확인·부존재확인소송, 이의재결 취소소송은 재결을 한 토지수용위원회가 피고다. 보상금증액청구소송은 사업시행자를 피고로 하는 당사자소송(형식적 당사자소송)이다.","c":"중"},"세무사2026_63-56":{"w":"행정소송법 제21조 1항: 법원은 취소소송을 당해 처분등에 관계되는 사무가 귀속하는 국가 또는 공공단체에 대한 당사자소송 또는 취소소송 외의 항고소송으로 변경하는 것이 상당하다고 인정할 때에는 청구의 기초에 변경이 없는 한 사실심의 변론종결시까지 원고의 신청에 의하여 결정으로 소의 변경을 허가할 수 있다.","c":"상"},"세무사2016_53-67":{"w":"경정청구기간이 지난 뒤에 한 경정청구는 법률상 신청권이 없어 이에 대한 거부가 항고소송의 대상인 처분이 되지 않는다.","c":"중"},"세무사2016_53-80":{"w":"대집행 제1차 계고처분 후 반복된 제2차 계고는 새로운 의무를 부과하지 않는 통지에 불과해 처분이 아니다.\n지목변경신청 거부, 행정규칙에 근거한 권리의무 변동 행위, 재임용 제외 결정, 건축신고 수리거부는 처분이다.","c":"중"},"세무사2017_54-47":{"w":"건축신고 반려행위는 판례상 항고소송의 대상인 처분이다.\n신체등위판정, 어업권면허 우선순위결정, 검사의 공소, 반복된 2차 독촉처분은 처분성이 없다.","c":"중"},"세무사2017_54-49":{"w":"지목변경신청 반려행위는 토지소유자의 법률상 지위에 영향을 주므로 처분이다.\n벌점 배점, 당연퇴직 인사발령, 공매통지, 혁신도시 입지 선정은 처분성이 부정된다.","c":"중"},"세무사2017_54-59":{"w":"ㄱ 세무조사결정, ㄴ 토지대장 직권말소, ㄹ 청소년유해매체물 결정·고시는 처분이다.\nㄷ 공정거래위원회의 고발조치는 처분이 아니다.","c":"중"},"세무사2017_54-61":{"w":"질서위반행위규제법에 따른 과태료 부과처분은 이의제기와 법원의 과태료 재판으로 다투며 항고소송의 대상이 아니다.\n개별공시지가결정, 표준약관 사용권장행위, 감액경정 후 남은 부분, 증액경정처분은 항고소송 대상이다.","c":"중"},"세무사2021_58-41":{"w":"조례안의 재의결은 지방자치법상 대법원에 제소할 수 있는 대상으로 행정소송의 대상이 된다.\n과태료 부과, 등기, 국회의원 제명, 구속영장 발부는 행정소송의 대상이 아니다.","c":"하"},"세무사2021_58-67":{"w":"재결주의가 적용되는 것은 감사원 재심의판정(ㄴ)과 특허심판원 심결(ㄷ)이다.\n소청심사위원회 결정과 국세기본법상 심판청구 결정은 원처분주의가 적용된다.","c":"중"},"세무사2021_58-68":{"w":"표준약관 사용권장행위, 종합쇼핑몰 거래정지 조치, 방송통신심의위원회의 시정요구, 교도소장의 접견내용 녹음·녹화 및 교도관 참여 지정행위는 판례상 모두 항고소송 대상인 처분이다.","c":"하"},"세무사2022_59-56":{"w":"진실규명결정(ㄱ), 건축협의 취소(ㄴ), 약제급여·비급여목록 및 급여상한금액표 고시(ㄹ)는 처분으로 인정된다.\n혁신도시 최종입지선정행위(ㄷ)는 처분이 아니다.","c":"하"},"세무사2023_60-76":{"w":"금융감독위원회의 부실금융기관 파산신청은 법원에 대한 신청행위로서 처분이 아니다.\n허가구역 지정, 용도변경신청 거부, 개별공시지가결정, 소득금액변동통지는 처분이다.","c":"중"},"세무사2023_60-77":{"w":"ㄱ 지방의료원 폐업결정, ㄴ 국가인권위원회 성희롱결정 및 시정조치권고, ㄹ 청구 방법과 다른 정보공개 결정은 처분이다.\nㄷ 4대강 살리기 마스터플랜은 행정계획의 발표로 처분이 아니다.","c":"중"},"세무사2024_61-78":{"w":"ㄱ 세무조사결정, ㄷ 소득금액변동통지, ㅁ 결손금 감액경정 통지는 처분이다.\nㄴ 공매통지와 ㄹ 국세환급금 결정은 처분이 아니다.","c":"중"},"세무사2024_61-79":{"w":"불가쟁력이 생긴 처분의 변경신청을 거부한 결정은 새로운 처분이 아니므로 항고소송의 대상이 될 수 없다.\n주민의 면허취소 신청 거부, 건축물대장 작성신청 반려, 환급신청 거부, 새로운 신청으로 볼 수 있는 이의신청 기각은 처분이다.","c":"중"},"세무사2025_62-50":{"w":"토지대장상 소유자명의변경신청 거부는 토지대장이 소유권 변동을 증명하는 효력이 없다는 이유로 처분성이 부정된다.\n직권말소, 건축물대장 작성·용도변경 거부, 지적공부 면적 정정신청 반려는 처분이다.","c":"하"},"세무사2025_62-57":{"w":"교원소청심사위원회의 결정은 원처분주의가 적용되어 징계처분을 대상으로 한다. 재결주의라는 ④가 옳지 않다.\n감사원 재심의, 중앙노동위원회 재심판정, 특허심판원 심결은 재결주의이고, 토지수용 이의재결은 원처분주의다.","c":"중"},"세무사2025_62-59":{"w":"ㄱ 개별공시지가결정, ㄴ 이행강제금 최초 독촉, ㄷ 지방의회 의장선임의결, ㄹ 금융감독원장의 문책경고는 모두 판례상 처분이다.","c":"하"},"세무사2025_62-80":{"w":"ㄹ O: 감사원의 징계요구에 대해 요구받은 기관(A시장)이 불이익을 받는 규정이 없으면 기관소송으로 제기한 소는 허용되지 않는다.\nㄱ X: 징계요구만으로는 대상 공무원의 권리·의무가 직접 변동되지 않는다.\nㄴ X: 시장에 대한 처분이 아니다.\nㄷ X: 재심의결정은 징계요구와 별도의 처분이 아니다.","c":"하"},"세무사2026_63-51":{"w":"국가인권위원회의 성희롱결정 및 시정조치권고, 소득금액변동통지, 지목변경신청 반려행위는 모두 판례상 항고소송 대상인 처분이다.","c":"중"},"세무사2021_58-52":{"w":"ㄱ O: 처분이 있음을 안 날은 유효한 처분이 있음을 안 날, 처분이 있은 날은 효력 발생일이다.\nㄴ X: 통지가 도달하면 알았다고 추정할 뿐 간주하지 않는다.\nㄷ X: 공시송달은 공고일부터 14일이 지나면 효력이 발생하지만, 이때 처분이 있음을 알았다고 보지 않는다.","c":"하"},"세무사2021_58-54":{"w":"ㄱ O: 납세고지처분에 대해 전심절차를 거쳤으면 가산금 징수처분은 별도로 거치지 않아도 된다.\nㄴ O: 행정심판전치 요건은 사실심 변론종결시까지 충족하면 된다.\nㄷ O: 동일한 처분에 대해 다른 사람이 이미 기각재결을 받은 때에는 전심 없이 소를 제기할 수 있다(제18조 3항).","c":"중"},"세무사2021_58-63":{"w":"처분이 있음을 안 날(5월 24일)부터 90일이 제소기간이다. 초일은 산입하지 않으므로 90일째는 8월 22일(일요일)이고, 말일이 일요일이면 다음 날 만료한다. 마지막 날은 8월 23일이다.","c":"상"},"세무사2022_59-44":{"w":"행정소송법 제5조는 국외에서의 소송행위 추완 기간을 14일에서 30일로, 제3자 재심청구 기간을 30일에서 60일로 늘린다. 소의 제기 기간은 현행 90일을 150일로 늘리는데, 이 지문은 60일을 기준으로 쓰였고 선지에 150일이 없어 ①이 정답으로 처리된다.","c":"의심"},"세무사2024_61-60":{"w":"처분 명의자가 A행정청이므로 권한이 B에 있고 A에 내부위임되었더라도 항고소송의 피고는 처분명의자 A다. 무효확인소송의 피고도 A다.\n① 중대명백한 하자가 있어도 취소소송으로 다투면 제소기간이 적용된다. ② 이의신청을 거친 경우 기산점은 이의신청 결과를 통지받은 날이다. ⑤ 재처분 의무는 거부처분 취소판결에 인정되고 징계처분 취소판결에는 없다.","c":"중"},"세무사2024_61-73":{"w":"변경재결로 영업정지가 과징금으로 바뀌면 원처분(2024.2.1.자 처분)이 변경된 내용으로 존속하므로 소송 대상은 2.1.자 과징금부과처분이다. 제소기간은 재결서 정본을 송달받은 날부터 계산한다.","c":"하"},"세무사2024_61-74":{"w":"필요적 전치주의에서 행정심판 청구 후 60일이 지나도 재결이 없으면 재결 없이 소를 제기할 수 있고(제18조 2항 1호), 재결이 있은 날부터 1년이 지나면 제기하지 못한다(제20조 2항).","c":"상"},"세무사2021_58-70":{"w":"집행정지는 항고소송에 인정된다. 무효확인소송(제38조 1항 준용)과 처분부존재확인소송에 인정된다.\n예방적 부작위소송은 허용되지 않고, 당사자소송에는 집행정지가 준용되지 않는다.","c":"중"},"세무사2022_59-65":{"w":"집행정지(제23조)는 취소소송에 규정되어 있고 무효등 확인소송에 준용된다(제38조 1항). 부작위위법확인소송과 당사자소송에는 준용되지 않는다.","c":"상"},"세무사2026_63-42":{"w":"행정소송규칙은 집행정지 종기를 본안판결 선고일부터 30일 이내의 범위에서 정하고, 당사자 의사, 회복하기 어려운 손해의 내용 및 성질, 본안 승소가능성 등을 고려해 달리 정할 수 있다고 한다.","c":"중"}};
